\label{def: pr}
A Hamiltonian diffeomorphism $\phi \in \operatorname{\mathrm{Ham}}(M,\omega)$ of a closed symplectic manifold $(M,\omega)$ is called an {\bf ${\mathbb{F}}_p$ Hamiltonian pseudo-rotation} if it has finitely many periodic points of periods being powers of $p$ and for all $k \geq 1$ there holds 
\begin{equation*}
N(\phi^{p^k}; {\mathbb{F}}_p) = \dim_{{\mathbb{F}}_p} H^*(M;{\mathbb{F}}_p).
\end{equation*}
We call $\phi$ a {\bf pseudo-rotation} if it has finitely many periodic points, and for every period $m \geq 1$, over every field ${\mathbb{K}}$ we have
\begin{equation*}
N(\phi^m;{\mathbb{K}}) = \dim_{{\mathbb{K}}} H^*(M;{\mathbb{K}})
\end{equation*}
for all such iterations.

\label{thm: hyperbolic}
Let $(M,\omega)$ be a closed symplectic manifold and $\phi \in \operatorname{\mathrm{Ham}}(M,\omega)$.                                                     
Suppose $\phi$ has finitely many periodic points, all of which are hyperbolic. Then for any prime $p$, and a class $u \in H^r(M;{\mathbb{F}}_p)$ with $r>n$ satisfying 
\begin{equation}\label{eq: triv St}
St_p(u) = c_p t^{r(p-1)/2}u,
\end{equation}
for some $c_p \in {{\mathbb F}_p}\setminus \{0\}$, we have ${\it QSt}_p(u) \neq St_p(u).$

\label{cor: generic}
Let $(M,\omega)$ be a closed symplectic manifold such that there exists a prime $p$ and a class $u \in H^r(M;{\mathbb{F}}_p)$ with $r>n$ such that 
\begin{equation*}
{\it QSt}_p(u) = St_p(u) = c_p t^{r(p-1)/2}u
\end{equation*}
for $0 \neq c_p \in {\mathbb{F}}_p$. Then any $C^2$-generic  Hamiltonian diffeomorphism $\phi \in \operatorname{\mathrm{Ham}}(M,\omega)$ has infinitely many periodic points.

\label{thm: Kunneth}
Let $X_1$ and $X_2$ be monotone symplectic manifolds such that $X_1 \times X_2$ is also monotone. Then for each prime $p$, the following diagram commutes up to the Koszul sign.
\begin{equation}\label{equation:kunneth-diagram-to-prove}
\vcenter{
\xymatrix{ H^*(X_1) \otimes H^*(X_2)
\ar[rrr]^-{{\it QSt}_p^{X_1} \otimes {\it QSt}_p^{X_2} }
\ar[d]_{\kappa}
&
&
&
H^*(X_1;\Lambda_{\mathcal{R}_p}^{\rm univ}) \otimes H^*(X_2; \Lambda_{\mathcal{R}_p}^{\rm univ}) \ar@{->}^-{\kappa}[d]
\\
H^*(X_1 \times X_2 )
\ar[rrr]_{{\it QSt}_p^{X_1\times X_2}}
&
&
&
H^*(X_1 \times X_2;\Lambda_{\mathcal{R}_p}^{\rm univ})
}}
\end{equation}
Here $\kappa$ is the ordinary Kunneth map. More precisely, if $a_1 \in H^*(X_1)$, $a_2 \in H^*(X_2)$, then 
\begin{equation*}
\kappa \left( {\it QSt}_p^{X_1}(a_1) \otimes {\it QSt}_p^{X_2}(a_2) \right) = (-1)^{|a_1||a_2|p(p-1)/2} {\it QSt}_{p}^{X_1 \times X_2} (\kappa(a_1 \otimes a_2)).
\end{equation*}

\label{thm: infinitely many}
Let $(M,\omega)$ be a closed symplectic manifold such that ${\it QSt}_p(\mu) = St_p(\mu)$ for                                                     
infinitely many primes $p$. Suppose $\phi \in \operatorname{\mathrm{Ham}}(M,\omega)$ has finitely many contractible fixed points and $N(\phi;{\mathbb{Q}}) = \dim_{{\mathbb{Q}}} H^*(M;{\mathbb{Q}})$. Then $\phi$ has infinitely many periodic points.

\label{thm:Floer-cochain}(\cite[Theorem A, Theorem B]{Bai_Xu_2025})
Given a nondegenerate $H$ and a compatible almost complex structure $J$, there exists a cochain complex \begin{equation*}
CF(H, J, \Xi; \Lambda_{\mathbb Z}^\Gamma)
\end{equation*}
of free graded $\Lambda_{\mathbb Z}^\Gamma$-modules, generated by capped 1-periodic orbits of $H$, whose differential depends on a system of choices $\Xi$. 

Moreover, for any two choices of almost complex structures $J_1$ and $J_2$, and two choices of the auxiliary data $\Xi_1$ and $\Xi_2$, there exists a chain homotopy equivalence
\begin{equation}\label{continuation_map}
     \Phi^{12}: CF(H, J_1, \Xi_1; \Lambda_{\mathbb Z}^\Gamma) \to CF(H, J_2, \Xi_2; \Lambda_{\mathbb Z}^\Gamma)
     \end{equation}
     whose homotopy class is independent of choices.

\label{defn:spec-inv}
Suppose $\alpha \in HF(M; \Lambda^\Gamma_{\mathbb K})$. We define the {\bf spectral invariant} for a nondegenerate Hamiltonian $H$ by
\begin{equation*}
c(\alpha,H) := \text{sup} \Big\{ a \in \mathbb{R} \ | \ \alpha \in \text{im}(\iota_a: HF(H; \Lambda_{\mathbb K}^\Gamma)^{>a} \to HF(M; \Lambda_{\mathbb K}^\Gamma)) \Big\}.
\end{equation*}

Let $(C, d)$ be a cochain complex over ${{\mathbb F}_p}$ with a ${\mathbb{Z}/p}$-action generated by a chain map $\iota: C \to C$. The {\bf Borel equivariant cochain complex} associated to $C$ and $\iota$ is the  graded cochain complex 
\begin{equation}\label{eq:equivariant-cohomology}
C_{{\mathbb{Z}/p}}:= C \otimes
 {\mathcal{R}_p},
\end{equation}
whose generators are of the form $x t^\alpha \theta^\beta$ for $x \in C$, $\alpha \geq 0$ and $\beta = 0, 1$. The  equivariant differential $d_{\mathbb{Z}/p}$ on $C_{{\mathbb{Z}/p}}$ is $t$-linear and determined by the following rules \begin{equation} \label{equation:equivariant-differential}\begin{array}{lclll} d_{\mathbb{Z}/p}(x \otimes t^i) & = & (dx)  \otimes  t^i & + & (-1)^{|x|}(\iota x - x) \otimes   \theta t^i \\ d_{\mathbb{Z}/p}(x \otimes \theta t^i) & = & (dx)  \otimes  \theta t^i & + & (-1)^{|x|} (1+\iota + \cdots + \iota^{p-1}) x \otimes  t^{i+1}.\end{array}\end{equation}
The equivariant cohomology $H_{{\mathbb{Z}/p}}(C)$ is the cohomology of $(C_{{\mathbb{Z}/p}}, d_{{\mathbb{Z}/p}})$.

Notice that the equivariant differential is not linear in $\theta$; hence $C_{{\mathbb{Z}/p}}$ is only a complex of ${\mathcal{K}_{0, p}}$-modules. However, the cohomology of $C_{{\mathbb{Z}/p}}$ is a module over ${\mathcal{R}_p}$. Indeed, a cochain map $\tilde\theta: C_{{\mathbb{Z}/p}}^* \to C_{{\mathbb{Z}/p}}^{*+1}$ is defined in \cite[Section 2d]{covariant-constant} by 
\begin{equation*}
\begin{split}
\tilde\theta( xt^k) = &\ (-1)^{|x|} xt^k \theta,\\
\tilde\theta( xt^k \theta) = &\ (-1)^{|x|} \Big( \iota x + 2 \iota^2 x + \cdots + (p-1) \iota^{p-1} x \Big) t^{k+1}.
\end{split}
\end{equation*}
On cohomology level it induces a well-defined ``multiplication by $\theta$'' map and hence $H_{{\mathbb{Z}/p}}(C)$ becomes an ${\mathcal{R}_p}$-module.

If $C$ is equipped with the trivial ${\mathbb{Z}/p}$-action, then the equivariant differential ${\mathcal{R}_p}$-linearly extends the differential on $C$ and the equivariant cohomology is 
\begin{equation*}
H_{{\mathbb{Z}/p}}(C) \cong H(C) \otimes {\mathcal{R}_p}.
\end{equation*}
Notice that this is an isomorphism of ${\mathcal{R}_p}$-modules.

For a general cochain complex $C$, the $p$-fold tensor power $C^{\otimes p} = C \otimes \dots \otimes C$ has a natural ${\mathbb{Z}/p}$-action by cyclically permuting the factors, resulting in an equivariant cochain complex with underlying space
\begin{equation*}
C^{\otimes p}_{{\mathbb{Z}/p}}:= C^{\otimes p} \otimes {\mathcal{R}_p}.
\end{equation*}

\label{lemma:quasi-Fr}(\cite[Section 7]{S-HZ})
Let $C$ be a cochain complex of finitely generated free $\Lambda_0^{\rm univ}$-modules. Then the quasi-Frobenius map $qF$ induces an isomorphism of $\Lambda_{0, {\mathcal{K}_p}}^{\rm univ}$-modules
\begin{equation}\label{eqn:Tate-power-iso}
  qF:  r_p^* \widehat{H}_{{\mathbb{Z}}/p}(C; \Lambda_{0, {\mathcal{K}_p}}^{\rm univ}) \to \widehat{H}_{{\mathbb{Z}}/p}(C^{\otimes p}; \Lambda_{0, {\mathcal{K}_p}}^{\rm univ} )
\end{equation}
where the left-hand-side of \eqref{eqn:Tate-power-iso} is regarded as the base-change
\begin{equation*}
\widehat H_{{\mathbb{Z}/p}}(C; \Lambda_{0, {\mathcal{K}_p}}^{\rm univ} ) \underset{\Lambda_{0, {\mathcal{K}_p}}^{\rm univ}}{\otimes} \Lambda_{0, {\mathcal{K}_p} }^{\rm univ}
\end{equation*}
via the ring isomorphism $r_p: \Lambda_{0, {\mathcal{K}_p}}^{\rm univ} \to \Lambda_{0, {\mathcal{K}_p}}^{\rm univ}$ induced by $q \mapsto q^{\frac{1}{p}}$.

As ${\mathcal{R}_p}$-modules, the equivariant Morse cohomology $HM_{{\mathbb{Z}/p}}(f)$ and the equivariant cohomology of the complex $CM(f)$ coincide. In particular, when ${\mathbb{Z}/p}$ acts trivially on $M$, as ${\mathcal{R}_p}$-modules, one has 
\begin{equation*}
HM_{{\mathbb{Z}/p}}(f) \cong HM(f) \otimes {\mathcal{R}_p}.
\end{equation*}

(\cite[Theorem H]{Bai_Xu_2025}) For any compact symplectic manifold $(M, \omega)$, the quantum Steenrod operation
\begin{equation*}
{\it QSt}_p: H (M; \Lambda^\Gamma) \to H^*(M; \Lambda_{\mathcal{R}_p}^\Gamma)
\end{equation*}
is well-defined. Moreover, its classical part coincides with the total Steenrod operation
\begin{equation*}
St_p: H (M; {\mathbb F}_p) \to H (M;{{\mathbb F}_p}) \otimes {\mathcal{R}_p}.
\end{equation*}
When $(M, \omega)$ is weakly monotone, this definition agrees with that of \cite{covariant-constant}.

(\cite[Theorem I]{Bai_Xu_2025})\label{thm211}
    Let $(M, \omega)$ be a compact symplectic manifold.                                                             

    \begin{enumerate}

        \item Let $H$ be a $1$-periodic Hamiltonian such that $H^{(p)}$ is nondegenerate. Then there exists a ${\mathbb Z}$-graded cochain complex of modules over $\Lambda_{{\mathcal{K}_{0, p}}}^\Gamma$, called the ${\mathbb{Z}}/p$-equivariant Floer cochain complex,
        \begin{equation*}
        (CF_{{\mathbb{Z}/p}} (H^{(p)}), d_{{\mathbb{Z}/p}})
        \end{equation*}
        with underlying space 
        \begin{equation*}
        CF_{{\mathbb{Z}/p}}(H^{(p)}) = \Big( CF(H^{(p)}) \widehat{\otimes} CM(g) \Big)^{\rm Inv}
        \end{equation*}
        where $d_{{\mathbb{Z}/p}}$ depends on an $\omega$-compatible almost complex structure $J$ and a system of choices. Moreover, its cohomology has a well-defined $\Lambda_{{\mathcal{R}_p}}^\Gamma$-module structure which extends the $\Lambda_{{\mathcal{K}_{0, p}}}^\Gamma$-module structure\footnote{The proof in \emph{loc.cit.} establishes the $\Lambda_{{\mathcal{K}_{0, p}}}^\Gamma$-module structure in the Morse setting, but the same argument applies to the Floer setting.}.




        \item For Hamiltonians $H_1, H_2$ with both $H_1^{(p)}$ and $H_2^{(p)}$ nondegenerate, there is a $\Lambda_{{\mathcal{K}_{0, p}}}^\Gamma$-linear chain homotopy equivalence
        \begin{equation*}
        (CF_{{\mathbb{Z}/p}} (H_1^{(p)}), d_{{\mathbb{Z}/p}}) \to (CF_{{\mathbb{Z}/p}}(H_2^{(p)}), d_{{\mathbb{Z}/p}})
        \end{equation*}
        (called an equivariant continuation map) whose homotopy class does not depend on any choices. Moreover, the resulting map on cohomology is linear over ${\mathcal{R}_p}$. Therefore, there is a well-defined invariant of $M$, called the {\bf ${\mathbb{Z}/p}$-equivariant Floer cohomology}, denoted by 
        \begin{equation*}
        HF_{\mathbb{Z}/p}(M; \Lambda_{{\mathcal{K}_{0, p}}}^\Gamma).
        \end{equation*}

\item For any Morse complex $CM(f)$ on $M$ and a Hamiltonian $H$ such that $H^{(p)}$ is nondegenerate, there exist $\Lambda_{{\mathcal{K}_{0, p}}}^\Gamma$-linear cochain maps
\begin{equation*}
{\it PSS}_{{\mathbb{Z}/p}}: CM(f) \otimes \Lambda_{{\mathcal{K}_{0, p}}}^\Gamma \otimes E(\theta) \to CF_{\mathbb{Z}/p}(H^{(p)})
\end{equation*}
and 
\begin{equation*}
{\it SSP}_{{\mathbb{Z}/p}}: CF_{{\mathbb{Z}/p}}(H^{(p)}) \to CM(f) \otimes \Lambda_{{\mathcal{R}_p}}^\Gamma
\end{equation*}
(the equivariant PSS and SSP maps) whose homotopy classes are well-defined. Moreover, the induced maps on cohomology are isomorphisms as graded $\Lambda_{{\mathcal{R}_p}}^\Gamma$-modules. In particular,
\begin{equation*}
HF_{{\mathbb{Z}/p}}(M) \cong H(M) \otimes \Lambda_{{\mathcal{R}_p}}^\Gamma.
\end{equation*}

\item (Notice that the equivariant PSS and SSP maps are not necessarily inverses to each other.) The difference
\begin{equation*}
{\it SSP}_{\mathbb{Z}/p} \circ {\it PSS}_{\mathbb{Z}/p} - {\rm Id}: H(M) \otimes \Lambda_{{\mathcal{R}_p}}^\Gamma \to H(M) \otimes \Lambda_{{\mathcal{R}_p}}^\Gamma.
\end{equation*}
strictly increases either the energy filtration or the $(t,\theta)$-grading.
\end{enumerate}

\label{thm213}
One can arrange the equivariant differentials $d_{{\mathbb{Z}/p}}$ on $CF_{\mathbb{Z}/p}(H^{(p)})$ such that under the above identification with $CF(H^{(p)}) \otimes {\mathcal{R}_p}$, $d_{{\mathbb{Z}/p}}^0 = d_{{\mathbb{Z}/p}}^{'0}  = d_{H^{(p)}}$ such that the complex $(CF(H^{(p)}), d_{H^{(p)}})$ of graded $\Lambda^\Gamma$-modules is filtered chain homotopy equivalent to a Floer complex $CF(H^{(p)})$ of the nondegenerate Hamiltonian $H^{(p)}$ (see Theorem \ref{thm:Floer-cochain}). 

\begin{enumerate}

    \item $d_{{\mathbb{Z}/p}}^1$ is a null-homotopic cochain map from $CF(H^{(p)})$ to itself.

    \item $d_{{\mathbb{Z}/p}}$ strictly increases the energy filtration.
\end{enumerate}

\label{lemma_local_eq_comparison}
The above definition of $HF_{\mathbb{Z}/p}^{\rm loc}(H^{(p)}, \overline{x}^{(p)})$ agrees with that of \cite{SZhao-pants}. More precisely, if $CF_{\mathbb{Z}/p}^{\rm loc}(H_1^{(p)}, \overline{x}^{(p)})_{\rm SZ}$ denotes the complex defined in \cite{SZhao-pants}, then there exists a ${\mathcal{K}_{0, p}}$-linear chain homotopy equivalence 
\begin{equation*}
CF_{\mathbb{Z}/p}^{\rm loc} (H_1^{(p)}, \overline{x}{}^{(p)})_{\rm SZ} \to CF_{\mathbb{Z}/p}^{\rm loc}(H_1^{(p)}, \overline{x}{}^{(p)})
\end{equation*}
which induces an isomorphism of ${\mathcal{R}_p}$-modules\footnote{The ${\mathcal{R}_p}$-module structure was claimed in \cite{SZhao-pants} without explicit construction.}
\begin{equation*}
HF_{\mathbb{Z}/p}^{\rm loc}(H^{(p)}, \overline{x}{}^{(p)})_{\rm SZ} \cong HF_{\mathbb{Z}/p}^{\rm loc} (H^{(p)}, \overline{x}{}^{(p)}).
\end{equation*}

\label{prop_local_eq_structure}
When $x$ is $p$-admissible and an isolated fixed point of $\phi^p$, there is an isomorphism of ${\mathcal{R}_p}$-modules 
\begin{equation}\label{eqn17}
HF_{\mathbb{Z}/p}^{\rm loc}(H^{(p)}, x^{(p)}) \cong HF^{\rm loc}(H^{(p)}, x^{(p)}) \otimes {\mathcal{R}_p}.
\end{equation}

\cite[Theorem J]{Bai_Xu_2025}\label{thm_FSt}
Let $H$ be a nondegenerate Hamiltonian on $(M, \omega)$ such that $H^{(p)}$ is also nondegenerate. Let $CF(H; \Lambda^\Gamma)$ be the Hamiltonian Floer cochain complex and $CF_{{\mathbb{Z}/p}}(H^{(p)})$ be the equivariant Floer cochain complex. Then there exists a well-defined homotopy class of $\Lambda_{{\mathcal{K}_{0, p}}}^\Gamma$-linear cochain maps
    \begin{equation*}
    \xymatrix{
 CF(H )^{\otimes p}_{{\mathbb{Z}/p}} = \Big( CF(H )^{\otimes p} \widehat{\otimes} CM(g) \Big)^{\rm Inv} \ar[r]^-{\widetilde{{\it FSt}}_p} & \Big( CF(H^{(p)} ) \otimes CM(g) \Big)^{\rm Inv}} =  CF_{{\mathbb{Z}/p}}(H^{(p)}) ,
    \end{equation*}
    called the {\bf equivariant pants product}.
    Its composition with the quasi-Frobenius map
    \begin{equation*}
    qF: H(CF(H)) \to H(CF(H )^{\otimes p}_{{\mathbb{Z}/p}})
    \end{equation*}
    defines a canonical ${{\mathbb F}_p}$-linear map
    \begin{equation*}
    {\it FSt}_p:= \widetilde{{\it FSt}}_p \circ qF: HF(M; \Lambda^\Gamma) \to HF_{{\mathbb{Z}/p}}(M; \Lambda^\Gamma_{{\mathcal{K}_{0, p}}})
    \end{equation*}
    called the {\bf Floer-theoretic Steenrod operation}.

\cite[Theorem J]{Bai_Xu_2025}\label{thm214}
Let $(M,\omega)$ be a closed symplectic manifold. Then for any prime $p$,                                                                                         
the following diagram commutes.
    \begin{equation}\label{equivpssisom}
\vcenter{ \xymatrix{
H^*(M;\Lambda^\Gamma ) \ar[r]^-{{\it QSt}_p} \ar[d]_{{\it PSS}} &
H^*(M;\Lambda_{{\mathcal{R}_p}}^\Gamma) 
\\ 
HF(M; \Lambda^\Gamma)
\ar[r]_-{{\it FSt}_p}
&
HF_{{\mathbb{Z}/p}}(M; \Lambda_{{\mathcal{K}_{0, p}}}^\Gamma) \ar[u]_{{\it SSP}_{{\mathbb{Z}/p}}}
}}
\end{equation}

\cite[Theorem M]{Bai_Xu_2025}\label{thm:pants-localization}
The equivariant pair-of-pants product induces an isomorphism on Tate cohomology which respects the energy filtration. As a consequence (which is not explicitly stated in \cite{Bai_Xu_2025}), after inverting $t \in {\mathcal{K}_{0, p}}$ and base change to the universal Novikov ring $\Lambda_{0,{\mathcal{K}_p}}^{\rm univ}$, $\widetilde{{\it FSt}}_p$ (see \eqref{canonical_submodule} and \eqref{eqn16}) induces a $\Lambda_{0, {\mathcal{K}_p}}^{\rm univ}$-linear chain map
    \begin{equation*}
    \widehat{{\it FSt}}_p: \widehat{CF(H; \Lambda_{0 }^{\rm univ})^{\otimes p}_{{\mathbb{Z}/p}}} \to 
    \widehat{ CF}_{{\mathbb{Z}/p}}(H^{(p)}; \Lambda_{0, {\mathcal{K}_p}}^{\rm univ});
    \end{equation*}
which is a chain homotopy equivalence.

\label{thm219}
For any prime $p$ and any Hamiltonian $H$ on $(M, \omega)$ such that both $H$ and $H^{(p)}$ are nondegenerate, there holds
\begin{equation}\label{eqn219}
    \beta_{\mathrm{tot}}(H^{(p)}) \geq p\cdot\beta_{\mathrm{tot}}(H).
\end{equation}

The comparison of total bar-lengths is via the Tate bar-length spectrum of $H^{(p)}$. By Theorem \ref{thm213}, one can write the differential $\widehat{d}_{{\mathbb{Z}/p}}$ on the Tate complex 
\begin{equation*}
\widehat{C}F_{\mathbb{Z}/p}(H^{(p)}) \cong \Big( CF(H^{(p)}) \oplus CF(H^{(p)}) \otimes \theta \Big) \otimes {\mathcal{K}_p}
\end{equation*}
in the form 
\begin{equation*}
\widehat{d}_{\mathbb{Z}/p}  =  \left[ \begin{array}{cc} d_{H^{(p)}} & S_p \\ 0 & d_{H^{(p)}} \end{array} \right] + t K
\end{equation*}
where $K$ does not decrease the $(t, \theta)$-degree. The leading $2\times 2$ matrix is the cone of $S_p$, whose differential is denoted temporarily by $d_{\rm Cone}$. Then one can use the argument in \cite{S-HZ}. More precisely, by \cite[Proposition 17]{S-HZ}, one has 
\begin{equation*}
\widehat{\beta}_{\rm tot}(H^{(p)}) \leq \beta_{\rm tot}(d_{\rm Cone})
\end{equation*}
where the latter is the total bar-length of $d_{\rm Cone}$. Moreover, as $S_p$ is null-homotopic (see Theorem \ref{thm213}) and strictly increases the energy filtration, by \cite[Lemma 18]{S-HZ}, one has 
\begin{equation*}
2 \beta_{\rm tot}(H^{(p)}) \geq \beta_{\rm tot}(d_{\rm Cone}).
\end{equation*}
Together with \eqref{eqn218}, one obtains \eqref{eqn219}.

\label{lemma222}
The above definition of ${\it FSt}_{p, x}^{\rm loc}$ coincides with the definition of \cite{SZhao-pants}. More precisely, the following diagram commutes.
\begin{equation*}
\xymatrix{  &  &      HF_{\mathbb{Z}/p}^{\rm loc}(H^{(p)}, x^{(p)}) \ar[dd] \\
HF^{\rm loc}(H, x) \ar[urr]  \ar[drr]  &  &  \\
&  &   HF_{\mathbb{Z}/p}^{\rm loc}(H^{(p)}, x^{(p)})_{\rm SZ} }
\end{equation*}
\qed

(cf. \cite[Section 10]{SZhao-pants})\label{thm_local_pants}
\begin{enumerate}

\item ${\it FSt}_{p, x}^{\rm loc}$ is an isomorphism.

\item When $x$ and $x^{(p)}$ are nondegenerate, $HF^{\rm loc}(H, x) \cong CF^{\rm loc}(H, x)$ is generated over $\Lambda^\Gamma$ by any capping $\overline{x}\in \widetilde{\mathcal O}(H)$ and $HF_{\mathbb{Z}/p}^{\rm loc}(H^{(p)}, x^{(p)})$ is generated over $\Lambda_{\mathcal{R}_p}^\Gamma $ by the corresponding capped orbit $\overline{x}^{(p)}$. Then there exists $\alpha$, $0 \leq \alpha \leq n(p-1)$ and $0 \neq c_x \in {{\mathbb F}_p}$ such that 
\begin{equation*}
{\it FSt}_{p, x}^{\rm loc}( \overline{x} ) = c_x t^\alpha \overline{x}^{(p)}.
\end{equation*}
\end{enumerate}

By Lemma \ref{lemma222}, one can use results from \cite{SZhao-pants}. There, a local equivariant pair-of-pants coproduct is constructed. When $x^{(p)}$ is nondegenerate, it has the form
\begin{equation*}
C_{p, x}^{\rm loc}: HF_{\mathbb{Z}/p}^{\rm loc}(H^{(p)}, x^{(p)}) \to H(CF^{\rm loc}(H, x)_{\mathbb{Z}/p}^{\otimes p}).
\end{equation*}
It was also proved that
\begin{equation*}
C_{p, x}^{\rm loc} \circ \widetilde{{\it FSt}}{}_{p,x}^{\rm loc} = (-1)^n t^{n(p-1)} {\rm Id}: H(CF^{\rm loc}(H, x)_{\mathbb{Z}/p}^{\otimes p}) \to H(CF^{\rm loc}(H, x)_{\mathbb{Z}/p}^{\otimes p}).
\end{equation*}
Note that $H(CF^{\rm loc}(H, x)_{\mathbb{Z}/p}^{\otimes p})$ is also 1-dimensional, generated by $\overline{x}^{\otimes p}$. Hence 
\begin{equation*}
\widetilde{{\it FSt}}{}_{p, x}^{\rm loc} (\overline{x}^{\otimes p}) = a_x \overline{x}^{(p)}
\end{equation*}
where $a_x \in {\mathcal{R}_p}\setminus \{0\}$ is a homogeneous divisor of $t^{n(p-1)}$. Hence $a_x$ can only be a nonzero multiple of a power of $t$ whose degree is at most $n(p-1)$. Lastly, the quasi-Frobenius map is simply $\overline{x} \mapsto \overline{x}^{\otimes p}$.

\label{prop31}
Let $(M,\omega)$ be a closed symplectic manifold. Consider a $1$-periodic Hamiltonian $H$ with $\mathrm{Fix}(\phi^1_H)$ finite. Then there exists $\epsilon_H>0$, and, for each ground field ${\mathbb{K}}$, there exists a ${\mathbb Z}$-graded complex of $\Lambda_{\mathbb K}^\Gamma$-modules
\begin{equation*}
C(H) = \left( \bigoplus_{x \in {\mathcal O}(H)}   HF^{{\rm loc}}(H, x;  \Lambda_{\mathbb K}^\Gamma), d_H \right)
\end{equation*}
graded by the (shifted) Conley--Zehnder index which satisfies the following conditions.                             





\begin{enumerate}

\item Let ${\mathcal A}_H: C(H) \to {\mathbb R} \cup \{+\infty\}$ be the energy filtration induced from ${\mathcal A}_{H, x}$ (see \eqref{eqn_local_action}). Then for any $y \in C(H)$, one has
\begin{equation*}
{\mathcal A}_H(d_H (y)) \geq  {\mathcal A}_H(y) + \epsilon_H.
\end{equation*}





\item $C(H)$ is chain homotopic to the Floer cochain complex $CF(G)$ (given by Theorem \ref{thm:Floer-cochain}) for any nondegenerate Hamiltonian $G$. 

\item For any $a, b \notin {\rm Spec}(H)$, the cohomology of the complex $C(H)^{(a, b)}$ agrees with $HF(H)^{(a, b)}$ which was defined by \eqref{eq: filtered-irrational}. 
\end{enumerate}

\label{cor32}
Let $p$ be a prime. Let $H$ be a Hamiltonian generating a Hamiltonian diffeomorphism $\phi$ which has finitely many contractible fixed points such that
\begin{equation*}
N(\phi; {{\mathbb F}_p}) = {\rm dim}_{{{\mathbb F}_p}} H^*(M; {{\mathbb F}_p}).
\end{equation*}
(For example, when $\phi$ is an ${{\mathbb F}_p}$ Hamiltonian pseudo-rotation.) Then the differential of the complex $C(H)$ vanishes.                                                                                                                                      
In particular, for all $a \in {\mathbb{R}} \setminus \operatorname{\mathrm{Spec}}(H),$ the cohomology $HF(H; \Lambda^\Gamma)^{>a}$ is given by the action-completion of 
\begin{equation*}
\bigoplus_{{\mathcal{A}}_H(\overline{x}) > a} HF^{{\rm loc}}(H,\overline{x}; {\mathbb F}_p).
\end{equation*}

By definition, one has
\begin{multline*}
{\rm dim}_{\Lambda^\Gamma} C(H) = \sum_{x \in {\mathcal O}(H)} {\rm dim}_{{{\mathbb F}_p}} HF^{\rm loc}(H, x; {{\mathbb F}_p}) = N(\phi; {{\mathbb F}_p}) \\
= {\rm dim}_{{{\mathbb F}_p}} H^*(M; {\mathbb F}_p) = {\rm dim}_{\Lambda^\Gamma} HF(M; \Lambda^\Gamma)
\end{multline*}
which, by (2) of Proposition \ref{prop31}, is also equal to the dimension of the cohomology of $C(H)$. Hence the differential on $C(H)$ vanishes.

\label{prop33b}
Let $H$ be a Hamiltonian on $(M, \omega)$ whose time-1 map has finitely many fixed points. Let $p$ be an odd prime such that ${\rm Fix}_c(\phi) = {\rm Fix}_c(\phi^p)$ and such that all fixed points are $p$-admissible. Then there exist $\epsilon_H>0$ and a complex of modules over $\Lambda_{{\mathcal{K}_{0, p}}}^\Gamma$
\begin{equation*}
C_{{\mathbb{Z}/p}}(H^{(p)}) = \left( \bigoplus_{x \in {\mathcal O}(H)} HF^{\rm loc}_{\mathbb{Z}/p}(H^{(p)}, x^{(p)}), d_{{\mathbb{Z}/p}} \right)
\end{equation*}
satisfying the following conditions.
\begin{enumerate}
    \item The complex $C_{{\mathbb{Z}/p}}(H^{(p)})$ is chain homotopic to $CF_{\mathbb{Z}/p}(G^{(p)})$ for any $G$ with $G^{(p)}$ being nondegenerate. In particular, the cohomology of $C_{{\mathbb{Z}/p}}(H^{(p)})$ is canonically isomorphic to $HF_{\mathbb{Z}/p}(M)$.

    \item The differential $d_{{\mathbb{Z}/p}}$ increases the energy filtration by $\epsilon_H$.
\end{enumerate}

\label{prop35}
Let $(M, \omega)$ be a closed symplectic manifold and $H$ be a 1-periodic Hamiltonian whose time-1 map $\phi$ has  finitely many fixed points such that ${\rm Fix}_c(\phi) = {\rm Fix}_c(\phi^p)$. Let $C(H)$ be the complex provided by Proposition \ref{prop31} and $C_{{\mathbb{Z}/p}}(H^{(p)})$ be the complex provided by Proposition \ref{prop33b}.        



Then there exists a cochain map
\begin{equation*}
\widetilde{P}: C(H)^{\otimes p}_{{\mathbb{Z}/p}} \to C_{{\mathbb{Z}/p}}(H^{(p)})                                            
\end{equation*}
and a decomposition 
\begin{equation*}
\widetilde{P} = \widetilde{P}^{\rm loc} + \widetilde{P}^{\rm big},
\end{equation*}
which satisfy the following conditions.
\begin{enumerate}

\item Let $P: H(C(H)) \to HF_{{\mathbb{Z}/p}}(H^{(p)})$ be the composition of $\widetilde{P}$ and the quasi-Frobenius map on the cohomology level. Then the following diagram commutes.
\begin{equation*}
\xymatrix{  H(C(H)) \ar[r]^-{P} \ar[d]_{\cong}  &   H(C_{{\mathbb{Z}/p}}(H^{(p)})) \ar[d]^{\cong} \\
            HF(M; \Lambda^\Gamma)  \ar[r]_-{{\it FSt}_p}   &      HF_{{\mathbb{Z}/p}}(M; \Lambda_{{\mathcal{K}_{0, p}}}^\Gamma )  } 
            \end{equation*}
Here the vertical arrows are provided by or induced from the ones of Proposition \ref{prop31} and Proposition \ref{prop33b}.





\item For any $x \in {\mathcal O}(H)$, $\widetilde{P}^{\rm loc}$ restricts to a $\Lambda_{{\mathcal{K}_{0, p}}}^\Gamma$-linear map
\begin{equation*}
\widetilde{P}^{\rm loc}_x: HF^{\rm loc}(H, x )^{\otimes p}_{{\mathbb{Z}/p}} \cong HF^{\rm loc}(H, x)^{\otimes p} \otimes {\mathcal{R}_p} \to HF_{{\mathbb{Z}/p}}^{\rm loc}(H^{(p)}, x^{(p)})
\end{equation*}
which coincides with the local equivariant pants product.

\item For any $a \in C(H)^{\otimes p}$, one has 
\begin{equation*}
{\mathcal A}_{H^{(p)}}(\widetilde{P}^{\rm loc} (a)) \geq {\mathcal A}_H^{\otimes p} (a).
\end{equation*}
Moreover, there exists $\epsilon_H>0$ such that for any $a \in C(H)^{\otimes p}_{\mathbb{Z}/p}$, one has 
    \begin{equation*}
    {\mathcal A}_{H^{(p)}}(\widetilde{P}^{\rm big}(a)) \geq {\mathcal A}_H^{\otimes p} (a) + \epsilon_H.
    \end{equation*}


\end{enumerate}

\label{cor35}
Under the assumption of Proposition \ref{prop33b} and Proposition \ref{prop35}, if $p$ is an odd prime\footnote{When $p=2$, we have $N^{(p)} = N$ and $\widehat{\beta}_{i}(H^{(p)}) = p \beta_i(H)$.}, then one has $N^{(p)} = 2 N$ and for each $i = 1, \ldots, N$, there holds
\begin{equation*}
\widehat{\beta}_{2i-1}(H^{(p)}) = \widehat{\beta}_{2i}(H^{(p)}) = p \beta_i(H).
\end{equation*}

Consider a version of the previous construction in this section over the universal Novikov ring $\Lambda_{0}^{\rm univ}$  as follows. Choose for each $x \in {\mathcal O}(H)$ a capping $\overline{x}$ and define 
\begin{equation*}
HF^{\rm loc}(H, x; \Lambda_0^{\rm univ}):= q^{- {\mathcal A}_H(\overline{x})} \Big( HF^{\rm loc}(H, \overline{x})  {\otimes} \Lambda_0^{\rm univ} \Big) \subset HF^{\rm loc}(H, x; \Lambda^{\rm univ})
\end{equation*}
and
\begin{equation*}
C(H; \Lambda_0^{\rm univ}):= \bigoplus_{x \in {\mathcal O}(H)} HF^{\rm loc}(H, x; \Lambda_0^{\rm univ}) \subset C(H; \Lambda^{\rm univ}).
\end{equation*}
Then $d_H$ canonically induces a $\Lambda_0^{\rm univ}$-linear differential on $C(H; \Lambda_0^{\rm univ})$. Similarly, one can define the Tate version 
\begin{equation*}
\widehat{C}_{{\mathbb{Z}/p}}(H^{(p)}; \Lambda_{0, {\mathcal{K}_p} }^{\rm univ}).
\end{equation*}
Then the cochain map $\widehat{P}$ of \eqref{eqn21} restricts to a $\Lambda_{0, {\mathcal{K}_p}}^{\rm univ}$-linear cochain map

\begin{equation*}
\widehat{P}_0: \widehat{ C(H; \Lambda_0^{\rm univ})^{\otimes p}_{{\mathbb{Z}/p}}} \to \widehat{C}_{{\mathbb{Z}/p}}(H^{(p)}; \Lambda_{0, {\mathcal{K}_p}}^{\rm univ}).
\end{equation*}
As the local restrictions are chain homotopy equivalences, $\widehat{P}_0$ induces an isomorphism of $\Lambda_{0, {\mathcal{K}_p}}^{\rm univ}$-modules
\begin{equation*}
\widehat{P}_0: H ( \widehat{ C (H; \Lambda_0^{\rm univ} )_{\mathbb{Z}/p}^{\otimes p}}  ) \to H( \widehat{C}_{{\mathbb{Z}/p}}(H^{(p)};\Lambda_{0, {\mathcal K}_p}^{\rm univ})).
\end{equation*}
Therefore, the Tate bar-length spectrum  is computed by
\begin{equation*}
\widehat{\beta}_{2i-1}(H^{(p)}) = \widehat{\beta}_{2i}(H^{(p)})  = p \beta_i(H). \qedhere
\end{equation*}

