Under the hypothesis of Proposition \ref{prop33b}, suppose in addition that the time-1 map $\phi$ of $H$ satisfies
\begin{align*}
    &\ {\rm Fix}_c(\phi) = {\rm Fix}_c(\phi^p),\ &\ N(\phi; {\mathbb F}_p) = N(\phi^p; {\mathbb F}_p) = {\rm dim}_{{\mathbb F}_p} H^*(M; {\mathbb F}_p).
\end{align*}
Then the differential $d_{{\mathbb{Z}/p}}$ of the complex of Proposition \ref{prop33b} vanishes.

\label{lemma37}
Let $p$ be an odd prime and $\phi \in {\rm Ham}(M, \omega)$. Suppose ${\rm Fix}_c(\phi) = {\rm Fix}_c(\phi^p)$ and all $x \in {\rm Fix}_c(\phi)$ are $p$-admissible. If the barcode of the complex $C(H^{(p)})$ constructed by Proposition \ref{prop31} has a nonzero bar, so does the barcode of the Tate complex $\widehat{C}_{\mathbb{Z}/p}(H^{(p)})$. In addition,
\begin{equation*}
\beta_1(H^{(p)}) \geq \widehat{\beta}_1(H^{(p)}).
\end{equation*}

\label{lma:div}
Under the assumption of Proposition \ref{prop31}, \ref{prop33b}, \ref{prop35}, suppose in addition that $x$ is $p$-admissible. Hence by Proposition \ref{prop_local_eq_structure}, one has 
\begin{equation*}
HF_{\mathbb{Z}/p}^{\rm loc}(H^{(p)}, \overline{x}^{(p)}) \cong HF^{\rm loc}(H^{(p)}, \overline{x}^{(p)}) \otimes {\mathcal{R}_p}.
\end{equation*}
Then the restriction of the local equivariant pants product $\widetilde{P}^{\rm loc}$ at $\overline{x}$ given by Proposition \ref{prop35} has a local decomposition written as 
\begin{equation*}
\widetilde{P}_{\overline{x}}^{\rm loc} = \sum_{2k \geq 0} t^k \widetilde{P}^{\rm loc}_{2k} + \sum_{2k+1 \geq 1} t^k \theta \widetilde{P}^{\rm loc}_{2k+1}
\end{equation*}
where 
\begin{equation*}
\widetilde{P}_i^{\rm loc}: HF^{\rm loc}(H, \overline{x})^{\otimes p} \to HF^{\rm loc}(H^{(p)}, \overline{x}{}^{(p)})
\end{equation*}
are the components. Then for any $y \in HF^{\rm loc}(H, \overline{x})$ with $\widetilde{P}^{\rm loc}(y\otimes \cdots \otimes y)\neq 0$, one has
\begin{equation*}
\inf \Big\{ i\ |\ \widetilde{P}_i^{\rm loc} (y \otimes \cdots \otimes y) \neq 0 \Big\} \leq 2n (p-1).
\end{equation*}

We first reduce the consideration to the case with a local normal form as in the proof of Proposition \ref{prop_local_eq_structure}.                                       
Recall that the local (equivariant) Floer cohomology is invariant under deformation as long as the fixed point remains uniformly isolated through the deformation. Moreover, the identifications between different moments through the deformation are given by certain continuation maps. As the local equivariant pants product is compatible with continuation maps, one can assume that $H$ has a product type. In other words, let $\phi$ be the time-1 map of $H$. Then we may assume that $M = X_1 \times X_2$ and $\phi = \phi_1 \times \phi_2$ are products. If $x = (x_1, x_2)$, then $x_1$ is a nondegenerate fixed point of $\phi_1$ and $x_2$ is a totally degenerate and isolated fixed point of $\phi_2$. 

To save notations, abbreviate $HF^{\rm loc}(\phi, x)$ by $HF^{\rm loc}(\phi)$ (and in other similar occasions) as the critical points in the consideration are clear from the context. Let
\begin{equation*}
\widetilde{P}_{x_i}^{\rm loc}:= \widetilde{{\it FSt}}{}_{p, x_i}^{\rm loc}: HF^{\rm loc}(\phi_i)^{\otimes p} \to HF_{\mathbb{Z}/p}^{\rm loc}(\phi_i^p) \cong HF^{\rm loc}(\phi_i^p) \otimes {\mathcal{R}_p}
\end{equation*}
be the local equivariant pants product and let 
\begin{equation*}
P_{x_i}^{\rm loc}: HF^{\rm loc}(\phi_i) \to HF_{\mathbb{Z}/p}^{\rm loc}(\phi_i^p)
\end{equation*}
be their compositions with the quasi-Frobenius map $y \mapsto y^{\otimes p}$.














The basic strategy in the rest of the proof is to use the Kunneth property of the local equivariant pants product (Proposition \ref{prop55}) and the leading order bounds of the equivariant pants product on the two factors.                                                                                                                                                                                                                                




Then by Proposition \ref{prop_local_eq_Kunneth} and Proposition \ref{prop55} proved below, the following diagram commutes up to the Koszul sign.
\begin{equation*}
\xymatrix{   HF^{\rm loc} (\phi)  \ar[rr]^{P^{\rm loc} }     &     &  HF_{\mathbb{Z}/p}^{\rm loc} (\phi^p)  \\
             HF^{\rm loc} (\phi_1) \otimes HF^{\rm loc} (\phi_2) \ar[rr]_-{P_{x_1}^{\rm loc} \otimes P_{x_2}^{\rm loc} } \ar[u]^{\kappa^{\rm loc}}  & &   HF_{\mathbb{Z}/p}^{\rm loc}  (\phi_1^p)  \underset{{\mathcal{R}_p}}{\otimes} HF_{\mathbb{Z}/p}^{\rm loc}  (\phi_2^p) \ar[u]_{\kappa_{\mathbb{Z}/p}^{\rm loc} }}
\end{equation*}
Notice that the non-equivariant Kunneth map $\kappa^{\rm loc}$ is an isomorphism. On the other hand, from the proof of Proposition \ref{prop_local_eq_structure} one knows that $\kappa_{\mathbb{Z}/p}^{\rm loc}$ is also an isomorphism, although it wouldn't be true if we drop the $p$-admissibility condition.

Now we prove that both $P_{x_1}^{\rm loc}$ and $P_{x_2}^{\rm loc}$ satisfy the bound we would like to prove. We first analyze the totally degenerate piece $P_{x_2}^{\rm loc}$. As $x_2$ is also $p$-admissible, by Proposition \ref{prop_local_eq_structure}, one has an isomorphism of ${\mathcal{R}_p}$-modules
\begin{equation*}
HF_{\mathbb{Z}/p}^{\rm loc}(\phi_2^p) \cong HF^{\rm loc}(\phi_2^p) \otimes {\mathcal{R}_p}.
\end{equation*}

\noindent {\it Claim.} If we decompose
\begin{equation*}
P_{x_2}^{\rm loc} = \sum_{2k\geq 0} t^k P_{x_2, 2k}^{\rm loc} + \sum_{2k+1\geq 1} t^k \theta P_{x_2, 2k+1}^{\rm loc},
\end{equation*}
then 
\begin{equation*}
P_{x_2, i}^{\rm loc} = 0 \ {\rm when}\ i > 2(p-1)n_2 = (p-1) {\rm dim}_{\mathbb R} X_2.
\end{equation*}

\noindent {\it Proof of the claim.} The basic idea is to reduce the consideration to local Steenrod operations on local Morse cohomology. By the argument of Proposition \ref{prop_local_eq_structure}, the local equivariant cohomology can be computed using an autonomous Hamiltonian $h$ and the isomorphism is provided by a continuation map. Therefore, the cochain level map ${\it FSt}_{p, x}^{\rm loc}$ can also be defined using the autonomous $h$, denoted by 
\begin{equation*}
P^{\rm loc}_{\rm Morse}: HM^{\rm loc}(h, 0) \to HM^{\rm loc}(h, 0) \otimes {\mathcal{R}_p}.
\end{equation*}









We know that the local Morse cohomology is identified with a relative cohomology $H^*(B, N)$ with $B$ being a $2n_2$-dimensional ball while $N \subset \partial B$ is a codimension zero submanifold with boundary. 

Using an argument analogous to \cite[Section 3.2]{wilk} for general primes $p$, one can show that $P_{\rm Morse}^{\rm loc}$ is identified with the classical Steenrod operation 
\begin{equation*}
{\it St}_p: H^*(B,N) \to H^*(B,N) \otimes {\mathcal{R}_p}
\end{equation*}
given by \cite[Equation (1.6)]{Seidel-formal}. By the classical theory of Steenrod operations, the coefficient of $t^\alpha \theta^\beta$ of $St_p(z)$ for $|z|=k$ vanishes when $2\alpha + \beta > k (p-1)$. As $H^*(B, N)$ has non-vanishing degrees up to ${\rm dim} B = 2n_2$, the assertion of the claim follows. (The required conclusion also follows directly from an analysis of the Morse moduli spaces defining $P_{\rm Morse}^{{\rm loc}}$, as in the proof of \cite[Proposition 3.3]{wilk}, specifically ``Axiom 5".) \hfill {\it End of the proof of the claim.}

On the other hand, the nondegenerate piece is an easy consequence of Theorem \ref{thm_local_pants}. If $e_1 \in HF^{\rm loc}(\phi_1)$ is a generator (which induces a corresponding generator $e_1^{(p)}$ of $HF_{\mathbb{Z}/p}^{\rm loc}  (\phi_1^p)$), then there exists $a_1 \leq n_1 (p-1)$ and $c_1 \neq 0$ such that
\begin{equation}\label{eqn25}
P^{\rm loc}_{x_1}  ( e_1 ) = c_1 t^{a_1} e_1^{(p)}.
\end{equation}














Now we can use the Kunneth property of the local equivariant pants product (Proposition \ref{prop55}). Let $e_1 \in HF^{\rm loc}(\phi_1; {\mathbb F}_p)$ be a generator and $y_2 \in HF^{\rm loc}(\phi_2; {\mathbb F}_p)$. Suppose $P^{\rm loc}( e_1 \otimes y_2 ) \neq 0$. Then by \eqref{eqn25} and the Kunneth property, one has
\begin{equation*}
\begin{split}
&\ \pm P^{\rm loc}( \kappa^{{\rm loc}}(e_1 \otimes y_2)) \\
= &\ \kappa_{\mathbb{Z}/p}^{\rm loc}    \Big( P^{\rm loc}_{x_1}(e_1) \otimes P^{\rm loc}_{x_2}(y_2) \Big) \\
= &\ \kappa_{\mathbb{Z}/p}^{\rm loc} \Big( c_1 t^{a_1} e_1^{(p)} \otimes P^{\rm loc}_{x_2} (y_2) \Big) \\
= &\ c_1 t^{a_1} \kappa_{\mathbb{Z}/p}^{\rm loc}  \Big( e_1^{(p)} \otimes P^{\rm loc}_{x_2} (y_2) \Big)\\
= &\ c_1 t^{a_1} \kappa_{\mathbb{Z}/p}^{\rm loc} \Big( \sum_{2k} t^k e_1^{(p)}\otimes P^{\rm loc}_{x_2, 2k}(y_2) + \sum_{2k+1} t^k \theta e_1^{(p)} \otimes P^{\rm loc}_{x_2, 2k+1}(y_2) \Big)\\
= &\ c_1 \Big( \sum_{2k} t^{a_1 + k} \kappa_{{\mathbb{Z}/p}}^{\rm loc}( e_1^{(p)} \otimes P_{x_2, 2k}^{\rm loc}(y_2) ) + \sum_{2k+1} t^{a_1 + k} \theta \kappa_{{\mathbb{Z}/p}}^{\rm loc}( e_1^{(p)} \otimes P_{x_2, 2k+1}^{\rm loc}(y_2)) \Big).
\end{split}
\end{equation*}
Here we used the property that $\kappa_{\mathbb{Z}/p}^{\rm loc}$ is ${\mathcal{R}_p}$-bilinear.

Now let $P^{\rm loc}_{x_2, i_2}(y_2)$ be the leading order term of $P_{x_2}^{\rm loc} (y_2)$. Notice that $\kappa_{\mathbb{Z}/p}^{\rm loc}$ does not decrease the $(t, \theta)$-grading and its leading order term is the non-equivariant Kunneth map $\kappa^{\rm loc}$, which is an isomorphism. Then the leading term of $P^{\rm loc}(\kappa^{\rm loc}(e_1 \otimes y_2))$ is a nonzero multiple of 
\begin{equation*}
\kappa^{\rm loc}(e_1^{(p)} \otimes P^{\rm loc}_{x_2, i_2}(y_2))
\end{equation*}
which has $(t, \theta)$-degree no greater than $2n(p-1)$.

\label{lemma:SDM}
Let $H$ be a 1-periodic Hamiltonian such that $\overline{x} \in \tilde {\mathcal O}(H)$ is a symplectically degenerate maximum (whose mean index, denoted by $\Delta$, is necessarily an integer). Denote $c = {\mathcal A}_H(\overline{x})$. Then for every sufficiently small $\epsilon > 0$, there exists a sufficiently large natural number $r_{\epsilon} > 0$ such that for all $r \geq r_{\epsilon}$ there exists $\delta = \delta_{\epsilon,r} \in (0,\epsilon)$ such that the following connecting homomorphism 
\begin{equation}\label{eq: connecting}
     HF^{r\Delta+n}(H^{(r)})^{(rc+\delta, rc+\epsilon)} \to HF^{r\Delta+n+1}(H^{(r)})^{(rc-\delta,rc+\delta)},\end{equation}
     associated to the short exact sequence
     \begin{equation*}
     \xymatrix{ 0 \ar[r] & C(H^{(r)})^{(rc-\delta, rc+\delta)} \ar[r] & C(H^{(r)})^{(rc-\delta, rc+\epsilon)} \ar[r] & C(H^{(r)})^{(rc + \delta, rc + \epsilon)} \ar[r] & 0 } 
     \end{equation*}
     is nontrivial.

The assertion follows from the methods of proof of \cite[Proposition 4.7]{Ginzburg-CC}, \cite[Theorem 1.18]{GG-ai}, and \cite[Theorem 1.3]{Hein-CCCY}. Indeed, \cite{Hein-CCCY} adapts the methods of \cite{Ginzburg-CC} to show that on an arbitrary closed symplectically Calabi--Yau manifold, there holds
    \begin{equation*}
    HF^{r\Delta+n+1}(H^{(r)})^{(rc+\delta, rc+\epsilon)} \neq 0.
    \end{equation*}  
The argument in \cite{Hein-CCCY} applies equally well for an arbitrary closed symplectic manifold, as it relies on a general decomposition theorem for filtered Floer homology and Ginzburg's arguments \cite{Ginzburg-CC} applied to the ``local summand" of the decomposition.

Furthermore, Ginzburg proves that the above connecting map is non-trivial in the aspherical case, and this extends, by applying Hein's decomposition, to the case of an arbitrary closed symplectic manifold.

\label{prop_carrier_iteration}
Under the assumption of Theorem \ref{thm: pr}, let $\phi\in {\rm Ham}(M)$ be an ${{\mathbb F}_p}$ Hamiltonian pseudo-rotation generated by a Hamiltonian $H$. Suppose ${\it QSt}_p(\mu) = St_p(\mu)$. Then there exists $\overline{x} \in \tilde {\mathcal O}(H)$ such that for all sufficiently large $k\geq 0$, 
\begin{equation*}
HF^{{\rm loc}, 2n} (H^{(p^k)}, \overline{x}^{(p^k)}; {{\mathbb F}_p}) \neq 0.
\end{equation*}

Assume on the contrary that ${\it QSt}_p(\mu) = St_p(\mu)$. Let $\phi$ be an ${{\mathbb F}_p}$ Hamiltonian pseudorotation generated by a Hamiltonian $H$. Let $\overline{x} \in \tilde {\mathcal O}(H)$ be provided by Proposition \ref{prop_carrier_iteration}. Then by Lemma \ref{lma:sdm}, for any  $k\geq 0$, the iteration $\overline{x}^{(p^k)}$ cannot be a symplectically degenerate maximum. Then for all $k\geq 0$, $\Delta(\overline{x}^{(p^k)}) \neq 0$. 

By Proposition \ref{prop_carrier_iteration},  when $k$ is sufficiently large, $HF^{{\rm loc}, 2n} (H^{(p^k)}, \overline{x}^{(p^k)}) \neq 0$. It follows that the mean index $\Delta(\overline{x}^{(p^k)})$ is negative because $HF^{\rm loc}(H^{(p^k)}, \overline{x}^{(p^k)})$ is supported over degrees in the interval $[-\Delta(\overline{x}^{(p^k)}), -\Delta(\overline{x}^{(p^k)}) + 2n]$ using our grading convention. By homogeneity of the mean index, we see that
\begin{equation*}
\Delta(\overline{x}^{(p^k)}) = p^k \Delta(\overline{x}) \xrightarrow{k \to \infty} -\infty. 
\end{equation*}
However, just as above, note that $HF^{\rm loc} (H^{(p^k)}, \overline{x}^{(p^k)})$ is supported over degrees in the interval $[-\Delta(\overline{x}^{(p^k)}), -\Delta(\overline{x}^{(p^k)}) + 2n]$, which contradicts the conclusion of Proposition \ref{prop_carrier_iteration} when $k$ is sufficiently large. Therefore, ${\it QSt}_p(\mu) \neq St_p(\mu)$.

We modify the pseudo-rotation to satisfy the condition of Lemma \ref{lma:div}. As $\phi$ is an ${{\mathbb F}_p}$ Hamiltonian pseudo-rotation, we may replace $\phi$ by $\phi^{p^k}$ for any $k\geq 0$. Hence we may assume that for all $x \in {\rm Fix}_c(\phi)$, 
\begin{equation*}
{\rm ker}(d\phi_x - {\rm Id}) = {\rm ker}(d\phi_x^p - {\rm Id}).
\end{equation*}

Now we translate the condition on the quantum Steenrod operation ${\it QSt}_p(\mu) = t^{n(p-1)} \mu$ to one about the equivariant pants product. Using Theorem \ref{thm214}, one has 
\begin{equation*}
{\it FSt}_p( {\it PSS}(\mu)) = t^{n(p-1)} {\it SSP}_{{\mathbb{Z}/p}}^{-1}(\mu) \in HF_{\mathbb{Z}/p}(M).
\end{equation*}
By abuse of notations, via ${\it PSS}$, we view $\mu$ as its image ${\it PSS}(\mu) \in HF(M)$. On the other hand, denote $\mu_{\mathbb{Z}/p}:= {\it SSP}_{\mathbb{Z}/p}^{-1}(\mu) \in HF_{\mathbb{Z}/p}(M)$. Then one has 
\begin{equation}\label{eqn27}
{\it FSt}_p(\mu) = t^{n(p-1)} \mu_{{\mathbb{Z}/p}} \in HF_{{\mathbb{Z}/p}}^{2n}(M; \Lambda^\Gamma) \otimes {\mathcal{R}_p}.
\end{equation}

Now one can localize the above equation to periodic orbits. Denote
\begin{equation*}
{\mathcal O}(H) = \{ x_1, \ldots, x_m\}.
\end{equation*}
By Proposition \ref{prop31}, as $\phi$ is an ${{\mathbb F}_p}$ Hamiltonian pseudo-rotation, for all $k\geq 0$, one has
\begin{equation*}
HF(M; \Lambda^\Gamma) \cong HF(H^{(p^k)}) = \bigoplus_{i = 1}^m  HF^{\rm loc}(H^{(p^k)}, x_i^{(p^k)}; \Lambda^\Gamma).
\end{equation*}
With respect to this decomposition, we can write 
\begin{equation*}
\mu = \sum_{i=1}^m \mu_i^{(p^k)},\ {\rm where}\ \mu_i^{(p^k)} \in HF^{{\rm loc}, 2n}  (H^{(p^k)}, x_i^{(p^k)}; \Lambda^\Gamma).
\end{equation*}
We consider a similar decomposition for the equivariant Floer cohomology. Applying Proposition \ref{prop33b} and Corollary \ref{cor36}, one has 
\begin{equation*}
HF_{{\mathbb{Z}/p}}(M; \Lambda_{{\mathcal{K}_{0, p}}}^\Gamma) \cong HF_{{\mathbb{Z}/p}} (H^{(p^k)}; \Lambda_{{\mathcal{K}_{0, p}}}^\Gamma) = \bigoplus_{i=1}^m HF^{\rm loc}(H^{(p^k)}, x_i^{(p^k)}; \Lambda_{{{\mathbb F}_p}}^\Gamma) \otimes {\mathcal{R}_p}.
\end{equation*}
So the class $\mu_{{\mathbb{Z}/p}}$ can be decomposed as 
\begin{equation}\label{equivariant_decomposition}
\mu_{{\mathbb{Z}/p}} = \sum_{i=1}^m \mu_{{\mathbb{Z}/p},i}^{(p^k)}(t, \theta),\ {\rm where}\ \mu_{{\mathbb{Z}/p},i}^{(p^k)}(t, \theta) \in HF^{{\rm loc}, 2n} (H^{(p^k)}, x_i^{(p^k)}; \Lambda^\Gamma) \otimes {\mathcal{R}_p}.
\end{equation}

{\it Claim A.} For all $k\geq 0$ and $i$, the leading order term $\mu_{{\mathbb{Z}/p},i}^{(p^k)}(0,0)$ coincides with $\mu_i^{(p^k)}$ up to higher energy terms. 

{\it Proof of Claim A.} On the cochain level, $\mu_{{\mathbb{Z}/p},i}^{(p^k)}(t, \theta)$ is realized by the inverse of the cochain-level equivariant SSP map. The involved moduli spaces contain the leading one corresponding to the non-equivariant SSP map, which gives $\mu_i^{(p^k)}$ up to high energy terms by the results in \cite[Section 13.7]{Bai_Xu_2025}. \hfill {\it End of the proof of Claim A.}

One can also view $\mu_{{\mathbb{Z}/p},i}^{(p^k)}(t, \theta)$ as a class in the Tate cohomology
\begin{equation*}
\widehat{HF}{}_{\mathbb{Z}/p}^{\rm loc} (H^{(p^k)}, x_i^{(p^k)}; \Lambda_{{\mathcal K}_p}^\Gamma) \cong HF^{{\rm loc}}(H^{(p^k)}, x_i^{(p^k)}; \Lambda^\Gamma) \otimes \Lambda_{{\mathcal K}_p} \otimes E(\theta).
\end{equation*}
What we do is to consider the ordinary and Tate spectral invariants and their ``carriers'' under the $p^k$-th iterations. 

{\it Claim B.} For all $k \geq 1$, there holds
\begin{equation*}
c(\mu, H^{(p^k)}) \geq \widehat{c}(\mu_{{\mathbb{Z}/p}}, H^{(p^k)}) = p c(\mu, H^{(p^{k-1})}) \geq p^k c(\mu, H)
\end{equation*}

{\it Proof of Claim B.}
The decomposition of $\mu$ implies that 
\begin{equation*}
c(\mu, H^{(p^k)}) = \min_i {\mathcal A}_{H^{(p^k)}}(\mu_i^{(p^k)}).
\end{equation*}
The Tate version implies
\begin{equation*}
\widehat{c}(\mu_{{\mathbb Z}/p}, H^{(p^k)}) = \min_i \widehat{\mathcal A}_{H^{(p^k)}}( \mu_{{\mathbb{Z}/p}, i}^{(p^k)}).
\end{equation*}
Claim A implies that 
\begin{equation*}
{\mathcal A}_{H^{(p^k)}}(\mu_i^{(p^k)}) \geq \widehat{\mathcal A}_{H^{(p^k)}}(\mu_{{\mathbb{Z}/p}, i}^{(p^k)}) \Longrightarrow c(\mu, H^{(p^k)}) \geq \widehat{c}(\mu_{{\mathbb{Z}/p}}, H^{(p^k)}).
\end{equation*}
Moreover, as the equivariant pants product rescales the spectral invariants by $p$, one has 
\begin{equation*}
\widehat{c}(\mu_{{\mathbb{Z}/p}}, H^{(p^{k+1})}) = \widehat{c}(t^{n(p-1)} \mu_{{\mathbb{Z}/p}}, H^{(p^{k+1})}) = p c(\mu, H^{(p^k)}).
\end{equation*}
Then inductively, $c(\mu, H^{(p^k)}) \geq p^k c(\mu, H)$. \hfill {\it End of proof of Claim B.}

Claim B has a local version. Suppose for some $i$, ${\mathcal A}_{H^{(p^k)}}(\mu_i^{(p^k)}) = c(\mu, H^{(p^k)})$.\footnote{One can roughly regard $x_i$, or its $p^k$-th iteration, as a spectral carrier.} Then  
\begin{equation}\label{eqn_local_growth}
{\mathcal A}_{H^{(p^{k+1})}}(\mu_i^{(p^{k+1})}) \geq c(\mu, H^{(p^{k+1})}) \geq p c(\mu, H^{(p^k)}) = p {\mathcal A}_{H^{(p^k)}}(\mu_i^{(p^k)}).
\end{equation}





The proposition will follow from a specific quantitative statement and induction. For each $k\geq 0$, define
\begin{equation*}
I^{(p^k)}:= \Big\{ i \in \{1, \ldots, m\}\ |\ p^k c(\mu, H) = {\mathcal A}_{H^{(p^k)}} (\mu_i^{(p^k)}) \Big\}.
\end{equation*}

{\it Claim C.} There holds 
\begin{equation}\label{carrier_iteration}
\bigcap_{k \geq 0} I^{(p^k)} \neq \emptyset.
\end{equation}

