\end{equation*}
gives 
\begin{equation*}
\widetilde{\kappa}_{\mathbb{Z}/p} \Big( (x_1^{\otimes p} \otimes (w_1 + \cdots + w_p) ) \otimes (x_2^{\otimes p} \otimes (w_1 + \cdots + w_p)) \Big) = \pm (\kappa(x_1 \otimes x_2))^{\otimes p} \otimes (w_1 + \cdots + w_p).
\end{equation*}
Here the sign comes from switching certain copies of $x_1$ and $x_2$. This claim essentially follows from the fact that in this situation equivariant transversality holds. Hence the flow line equation in $X_1 \times X_2$ and the Y-shaped gradient tree equation in $S^\infty$ are decoupled (see Remark \ref{remark52}). This verifies the commutativity (up to signs) of the diagram.

\label{prop55}
Given symplectic manifolds $X_1, X_2$ equipped with Hamiltonians $H_1, H_2$, and an isolated $\overline{x}_i \in \tilde {\mathcal O}(H_i)$ such that $\overline{x}_i^{(p)} \in \tilde {\mathcal O}(H_i^{(p)})$ is also isolated, the following diagram commutes up to the Koszul sign. 
\begin{equation*}
\xymatrix{ HF^{\rm loc} (H_1, \overline{x}_1) \underset{{{\mathbb F}_p}}{\otimes} HF^{\rm loc} (H_2, \overline{x}_2) \ar[rr]^-{{\it FSt}_p^{\rm loc} \otimes {\it FSt}_p^{\rm loc}} \ar[d]_{\kappa^{\rm loc}}   &     &HF^{\rm loc}_{\mathbb{Z}/p} (H_1^{(p)}, \overline{x}_1^{(p)}) \otimes HF_{\mathbb{Z}/p}^{\rm loc} (H_2^{(p)}, \overline{x}_2^{(p)}) \ar[d]^{\kappa^{\rm loc}_{{\mathbb{Z}/p}}}\\
     HF^{\rm loc} (H_1 \times H_2, \overline{x}_1\times \overline{x}_2 ) \ar[rr]_{{\it FSt}_p^{\rm loc}} & &   HF_{\mathbb{Z}/p}^{\rm loc} (H_1^{(p)}\times H_2^{(p)}, \overline{x}_1^{(p)}\times \overline{x}_2^{(p)} )  }.
\end{equation*}

The proof is similar to that of Theorem \ref{thm: Kunneth}. The idea is illustrated in Figure \ref{figure_Kunneth_fst}. 
\begin{figure}[h]
    \centering
    \includegraphics[width=1.1\linewidth]{Kunneth_fst.pdf}
    \caption{Kunneth property of the local equivariant Floer cohomology. The figure on the left corresponds to the composition $\kappa_{{\mathbb{Z}/p}}^{\rm loc} \circ ({FSt}_p^{\rm loc} \otimes {FSt}_p^{\rm loc})$ while the figure on the right corresponds to the composition ${FSt}_p^{\rm loc} \circ \kappa^{\rm loc}$.}
    \label{figure_Kunneth_fst}
\end{figure}
We first choose data so that all objects and arrows appearing in the commutative diagram can be defined on the chain level.

\begin{enumerate}

\item Choose nondegenerate perturbations $G_i$ of $H_i$ and an almost complex structure $J_i$ for which the local Floer cochain complexes $CF^{\rm loc}(H_i, G_i, \overline{x}_i)$ are defined. In this way, the local Floer cochain complex $CF^{\rm loc}(H_1 \times H_2, G_1 \times G_2, \overline{x}_1\times \overline{x}_2)$ is also defined using the product data, giving
\begin{equation*}
CF^{\rm loc}(H_1\times H_2, G_1 \times G_2, \overline{x}_1 \times \overline{x}_2) \cong CF^{\rm loc}(H_1, G_1, \overline{x}_1) \otimes CF^{\rm loc}(H_2, G_2, \overline{x}_2).
\end{equation*}
This isomorphism coincides with the chain-level Kunneth map $\kappa^{\rm loc}$, which can be defined following the line in Section \ref{subsec:equiv-kunneth}. From now on, the almost complex structures will be fixed and we omit the discussion on the dependence on them.

\item To define the local equivariant complexes $CF_{{\mathbb{Z}/p}}^{\rm loc}(H_i^{(p)}, G_i^{(p)}, \overline{x}_i^{(p)})$, we also choose a family of perturbations
\begin{equation*}
{\mathscr G}_{i,v}^{eq}: S^1 \times X_i \to {\mathbb R}, \ v \in S^\infty
\end{equation*}
of $G_i^{(p)}$ so the complex is defined. 

\item From now on, we drop from the notations the dependence on $H_1$ and $H_2$ as all further constructions only depend on $G_1$ and $G_2$. To define the local equivariant complex for the product $G_1^{(p)} \times G_2^{(p)}$, we choose another perturbation
\begin{equation*}
{\mathscr G}_{\infty,v}^{eq}: S^1 \times X_1 \times X_2 \to {\mathbb R}, \ v \in S^\infty
\end{equation*}
so the complex $CF_{{\mathbb{Z}/p}}^{\rm loc}(G_1^{(p)} \times G_2^{(p)}, \overline{x}_1^{(p)} \times \overline{x}_2^{(p)})$ is defined.

\item Choose a family of vector fields $Y_s$ on $S^\infty$ parametrized by $s \in T_{2, 1}$ so that the multiplicative structure ${\mathcal{R}_p} \otimes {\mathcal{R}_p} \to {\mathcal{R}_p}$ is defined. Then choose a family 
\begin{equation*}
\tilde {\mathscr G}_{s, v}^{eq}: \tilde S \times X_1 \times X_2 \to {\mathbb R},\ s \in T_{2, 1},\ v \in S^\infty
\end{equation*}
which connects ${\mathscr G}_{1,v}^{eq} \times {\mathscr G}_{2, v}^{eq}$ and ${\mathscr G}_{\infty, v}^{eq}$ so that the chain-level equivariant Kunneth map
\begin{equation*}
\kappa^{\rm loc}_{{\mathbb{Z}/p}}: CF_{{\mathbb{Z}/p}}^{\rm loc} (G_1^{(p)}, \overline{x}_1^{(p)}) \otimes CF_{{\mathbb{Z}/p}}^{\rm loc} (G_2^{(p)}, \overline{x}_2^{(p)} ) \to CF_{{\mathbb{Z}/p}}^{\rm loc} (G_1^{(p)}\times G_2^{(p)}, \overline{x}_1^{(p)} \times \overline{x}_2^{(p)})
\end{equation*}
is defined.


\item Choose ${\mathbb{Z}/p}$-equivariant family of connections on the trivial ${\rm Ham}(X_i)$-bundle on $\tilde S$ denoted by
\begin{equation*}
\sigma_{i, v}^{eq},\ v \in S^\infty
\end{equation*}
which is equal to $G_i dt$ on each of the incoming cylindrical ends and which is equal to ${\mathscr G}_i^{eq}$ on the positive cylindrical end, to define the chain level equivariant pair-of-pants product
\begin{equation*}
\widetilde{FSt}{}_p^{{\rm loc}}: CF^{\rm loc}(G_i, \overline{x}_i)^{\otimes p}_{{\mathbb{Z}/p}} \to CF^{\rm loc}_{{\mathbb{Z}/p}}(G_i^{(p)}, \overline{x}_i^{(p)}).
\end{equation*}

\item Choose a ${\mathbb{Z}/p}$-equivariant family of connections on the trivial ${\rm Ham}(X_1\times X_2)$-bundle over $\tilde S$ denoted by 
\begin{equation*}
\sigma_{\infty, v}^{eq},\ v \in S^\infty
\end{equation*}
which is equal to $(G_1 \times G_2) dt$ on each of the incoming cylindrical ends and is equal to ${\mathscr G}_\infty^{eq} dt$ on the positive cylindrical end, to define the chain-level equivariant pair-of-pants product
\begin{equation*}
\widetilde{FSt}{}_p^{X_1\times X_2}
\end{equation*}


\end{enumerate}

Now we would like to choose a family of connections on the trivial ${\rm Ham}(X_1)\times {\rm Ham}(X_2)$-bundle over $\tilde S$, denoted by 
\begin{equation*}
\tilde \sigma_{\rho, v_1, v_2}^{eq},\ \rho \in {\mathbb R}, v_1, v_2 \in S^\infty
\end{equation*}
satisfying
\begin{enumerate}
    \item $\tilde \sigma_{\rho, v_1, v_2}^{eq}$ is ${\mathbb{Z}/p}$-equivariant with respect to the diagonal action on $S^\infty \times S^\infty \times \tilde S$.

    \item For all $\rho$, on each of the negative cylindrical ends of $\tilde S$, $\tilde \sigma_{\rho, v_1, v_2}^{eq}$ coincides with $(G_1 \times G_2) dt$. 

    \item For all $\rho$, on the positive cylindrical end of $\tilde S$, $\tilde \sigma_{\rho, v_1, v_2}^{eq}$, when restricted to the diagonal of $S^\infty$, coincides with ${\mathscr G}_{\infty, v}^{eq} dt$.

    \item When $\rho \ll 0$, $\tilde \sigma_{\rho, v_1, v_2}^{eq}$ coincides with $\sigma_{1, v_1}^{eq}\times \sigma_{2, v_2}^{eq}$.

    \item When $\rho \gg 0$, $\tilde \sigma_{\rho, v_1, v_2}^{eq}$, when restricted to the diagonal $v = v_1 = v_2$ of $S^\infty$, coincides with $\sigma_{\infty, v}^{eq}$.

\end{enumerate}

We still use the canonical map $T_{2,1} \to {\mathbb R}$. For $i = 1, 2$, choose $\overline{x}_{i, 1}, \ldots, \overline{x}_{i, p} \in \tilde {\mathcal O}(G_i, \overline{x}_i)$, $\overline{y}_i \in \tilde {\mathcal O}(G_i^{(p)}, \overline{x}_i^{(p)})$. Choose $w_1, w_2, w_\infty \in {\rm crit}(g)$. Then for each fixed $\rho$, define the moduli space ${\mathcal M}_\rho$ as follows. When $\rho \leq 0$ resp. $\rho \geq 0$, ${\mathcal M}_\rho$ consists of pairs $(u, \zeta)$ where $u: \tilde S \to X_1 \times X_2$ is a smooth map, $\zeta = (\zeta_1, \zeta_2, \zeta_\infty): T_{2,1} \to S^\infty$ is a $Y$-perturbed gradient tree, such that 
    \begin{equation*}
    (\nabla^{\tilde \sigma_{\rho, \zeta_1(\rho), \zeta_2(\rho)}^{eq}} u)^{0,1} = 0\ {\rm resp.}\ (\nabla^{\tilde \sigma_{\rho, \zeta_\infty(\rho), \zeta_\infty(\rho)}^{eq}} u)^{0,1} = 0
    \end{equation*}
    and such that $u$ is asymptotic to $\overline{x}_{1, k} \times \overline{x}_{2, k}$ along the $k$-th negative end and asymptotic to $\overline{y}_1 \times \overline{y}_2$ along the positive end, while $\zeta$ is asymptotic to $w_1, w_2, w_\infty$ respectively along the corresponding edges. Define
    \begin{equation*}
    {\mathcal M}_\pm:= \bigsqcup_{\pm \rho \geq 0} {\mathcal M}_\rho.
    \end{equation*}
    One can see that each ${\mathcal M}_\rho$ is the zero locus of a smooth Fredholm section of a certain Banach vector bundle. Moreover, by choosing $\tilde \sigma_{\rho, v_1, v_2}^{eq}$ generically, one can make ${\mathcal M}_\pm$ together with ${\mathcal M}_0$ regular. One can also compactify the moduli space ${\mathcal M}_\pm$ by suitably adding broken configurations (notice that in this local situation, sphere bubbling won't happen). Then when the index of an individual moduli space ${\mathcal M}_\rho$ is zero, the compactifications $\overline{\mathcal M}_\pm$ are compact 1-dimensional topological manifolds with boundary. Then the union of $\overline{\mathcal M}_\pm$ along ${\mathcal M}_0$ defines a chain homotopy between the two cochain maps. The first one, corresponding to the boundary $\rho = -\infty$, is the composition 
    \begin{multline*}
    \widetilde{\kappa}_{{\mathbb{Z}/p}}^{\rm loc} \circ (\widetilde{\widetilde{FSt}}{}_p^{\rm loc} \otimes \widetilde{\widetilde{FSt}}{}_p^{\rm loc}): \\
    \Big( CF^{\rm loc}(H_1, \overline{x}_1)^{\otimes p} \otimes CM(g) \Big) \otimes  \Big( CF^{\rm loc}(H_2, \overline{x}_2)^{\otimes p} \otimes CM(g) \Big) \\
    \to CF^{\rm loc}( H_1^{(p)}\times H_2^{(p)}, \overline{x}_1^{(p)}\times \overline{x}_2^{(p)}) \otimes CM(g).
    \end{multline*}
    The second one, corresponding to the boundary $\rho = +\infty$, is the composition
    \begin{equation*}
    \widetilde{\widetilde{FSt}}{}_p^{\rm loc} \circ \widetilde{\kappa}^{\otimes p}
    \end{equation*}
    between the same pair of cochain groups. The chain homotopy is ${\mathbb{Z}/p}$-equivariant. Hence we can restrict to the ${\mathbb{Z}/p}\times {\mathbb{Z}/p}$-fixed subspace, which gives a chain homotopy between
    \begin{equation*}
    \widetilde{\kappa}{}_{{\mathbb{Z}/p}}^{\rm loc} \circ ( \widetilde{FSt}{}_p^{\rm loc}\otimes \widetilde{FSt}{}_p^{\rm loc}): CF^{\rm loc}(H_1, \overline{x}_1)^{\otimes p}_{{\mathbb{Z}/p}} \otimes CF^{\rm loc}(H_2, \overline{x}_2)^{\otimes p}_{{\mathbb{Z}/p}} \to CF^{\rm loc}_{{\mathbb{Z}/p}}(H_1^{(p)}\times H_2^{(p)}, \overline{x}_1^{(p)}\times \overline{x}_2^{(p)}).
    \end{equation*}
    and $\widetilde{FSt}{}_p^{\rm loc} \circ \widetilde{\kappa}{}_{{\mathbb{Z}/p}}^{\otimes p}$ between the same pair of groups. Hence as maps between cohomology, one has the equality
    \begin{equation*}
    \kappa_{{\mathbb{Z}/p}}^{\rm loc} \circ ({FSt}_p^{\rm loc} \otimes {FSt}_p^{\rm loc}) = {FSt}_p^{\rm loc} \circ \kappa_{{\mathbb{Z}/p}}^{\otimes p}.
    \end{equation*}
Lastly, one has the following commutative diagram (which can be proved exactly the same as Lemma \ref{Lemma_Kunneth_qF}).
\begin{equation*}
\xymatrix{  HF^{\rm loc}(H_1, \overline{x}_1) \otimes HF^{\rm loc}(H_2, \overline{x}_2) \ar[rr]^-{qF \otimes qF} \ar[d]_{\kappa^{\rm loc}} & & H ( CF^{\rm loc}(H_1, \overline{x}_1)^{\otimes p}_{{\mathbb{Z}/p}}) \otimes H( CF^{\rm loc}(H_2, \overline{x}_2)^{\otimes p}_{{\mathbb{Z}/p}}) \ar[d]^{\kappa_{{\mathbb{Z}/p}}}\\
HF^{\rm loc}(H_1 \times H_2, \overline{x}_1 \times \overline{x}_2) \ar[rr]_-{qF}  &   &     H(CF^{\rm loc}(H_1\times H_2, \overline{x}_1\times \overline{x}_2)^{\otimes p}_{{\mathbb{Z}/p}} )   }
\end{equation*}
Then the proof this proposition is finished.

The quantum Steenrod operation ${\it QSt}^{\rm Morse}_p$ defined in Subsection \ref{subsection52} is determined by ${\it QSt}^{\rm Morse}_{p,i,A}$ in the same way as $QSt^{\rm cell}_{p,i,A}$ determines $QSt^{\rm cell}_p$. More precisely, for any Morse cocycle $\alpha\in CM(f)$, one has 
\begin{equation*}
QSt^{\rm Morse}_{p, A} ([\alpha]) = \big[\Psi \left(  \sum_{k=0}^\infty \Big( QSt^{\rm Morse}_{p,2k, A}  (\alpha \otimes \cdots \otimes \alpha ) \otimes t^k + QSt^{\rm Morse}_{p,2k+1, A}  (\alpha \otimes \cdots \otimes \alpha) \otimes t^k \theta \Big) \right)\big].
\end{equation*}

To simplify notations, we omit the superscript ``Morse" in this proof. We may assume that $\alpha$ is a single critical point; the case when $\alpha$ is a linear combination of critical points only adds notational complexities. Consider the chain
\begin{equation*}
\tilde \alpha^p:=\sum_{l=1}^p \alpha \otimes \cdots \otimes \alpha \otimes w_0^l\in CM(f)^{\otimes p} \otimes CM(g).
\end{equation*}
As $\alpha$ is a cocycle, one can see that $\tilde \alpha^p$ is $d_{{\mathbb{Z}/p}}$-closed. Now by the definition of the chain map $\widetilde{\widetilde{QSt}}_{p, A}$ and the ${\mathbb{Z}/p}$-equivariance of the counts, one has
\begin{equation*}
\begin{split}
\widetilde{\widetilde{QSt}}{}_{p, A}(\tilde \alpha^p) = &\ \sum_{y \in {\rm crit}(f)} \sum_{l=1}^p \sum_{w \in {\rm crit}(g)} \#_p {\mathcal M}_{w_0^l, w}(A; \alpha, \ldots, \alpha, y) \cdot y \otimes w\\
= &\ \sum_{y \in {\rm crit}(f)} \sum_{i\geq 0} \left( \sum_{l=1}^p  \#_p {\mathcal M}_{w_0^l, w_i^1} (A; \alpha, \ldots, \alpha, y) \cdot y \right) \otimes \sum_{l=1}^p \tau^{l-1}(w_i^1)\\
= &\  \sum_{y \in {\rm crit} (f)} \sum_{i\geq 0} \left( \#_p {\mathcal M}{}_{P_i}(A; \alpha, \ldots, \alpha, y) \cdot y  \right) \otimes \sum_{l=1}^p w_i^l\\
= &\ \Psi \left( \sum_{k=0}^\infty QSt_{p,2k,A} (\alpha \otimes \cdots \otimes \alpha) \otimes t^k + \sum_{k=0}^\infty QSt_{p,2k+1,A} (\alpha \otimes \cdots \otimes \alpha) \otimes t^k \theta \right).
\end{split}
\end{equation*}
As the cohomology classes of both sides are well-defined, the lemma follows.

\label{lemma_QST_comparison}
Fix $A \in H_2(M; {\mathbb Z})$ and $i \geq 0$. For any generic inhomogeneous term $\nu_{v, z, x}^{eq}$, for any Morse cocycle $\alpha\in CM(f)$, the two Morse cocycles 
\begin{equation*}
QSt^{\rm Morse}_{p,i,A} (\alpha \otimes \cdots \otimes \alpha),\ QSt^{\rm cell}_{p,i,A}(\alpha \otimes \cdots \otimes \alpha)
\end{equation*}
are cohomologous.

\label{lemmaa4}
There exists a sequence of piecewise smooth chains $B_i \in C_i(S^i; {\mathbb Z}) \subset C_i(S^\infty; {\mathbb Z})$ for $i \geq 1$ satisfying
\begin{equation*}
P_i - \Delta_i = \left\{ \begin{array}{cc}  \partial B_{2k+1},\ &\ i = 2k,\\
                                            \tau(B_{2k+1}) - B_{2k+1} + \partial B_{2k+2},\ &\ i = 2k+1.\end{array} \right.
                                            \end{equation*}

$\Delta_0 = P_0$ is obvious and $\Delta_1 = P_1$ because they are both the unique positively oriented segment of $S^1\subset S^\infty$ between $\Delta_0$ and $\tau(\Delta_0)$. Hence we can choose $B_1 = 0$, $B_2 = 0$. 

For any positive even degree $i = 2k$, by the differential of the Morse cochain complex $CM(g)$, one has
\begin{equation*}
\partial P_{2k} = \sum_{l=1}^p \tau^{l-1}( P_{2k-1}).
\end{equation*}
Together with \eqref{equation:d-delta}, one obtains
\begin{equation*}
\partial( P_{2k} - \Delta_{2k}) = \sum_{l=1}^p \big( \tau^{l-1}(P_{2k-1}) - \tau^{l-1}(\Delta_{2k-1}) \big).
\end{equation*}
Notice that as chains, the sphere $S^{2k-1}$ can be written as
\begin{equation*}
S^{2k-1} = \sum_{l=1}^p \tau^{l-1}(\Delta_{2k-1}) = \sum_{l=1}^p \tau^{l-1}(P_{2k-1}).
\end{equation*}
It follows that $\partial (P_{2k} - \Delta_{2k}) = 0$. As $S^\infty$ is contractible, there hence exists $B_{2k+1} \in C_{2k+1}(S^{2k+1};{\mathbb Z})$ such that
\begin{equation*}
P_{2k} - \Delta_{2k} = \partial B_{2k+1}.
\end{equation*}
For any positive odd degree $i = 2k+1$, by the differential of the Morse cochain complex $CM(g)$, one has 
\begin{equation*}
\partial P_{2k+1} = \tau(P_{2k}) - P_{2k}.
\end{equation*}
Then together with \eqref{equation:d-delta}, one has 
\begin{equation*}
\partial( P_{2k+1} - \Delta_{2k+1}) = (\tau - {\rm Id}) ( P_{2k} - \Delta_{2k}) = (\tau - {\rm Id}) \partial B_{2k+1}.
\end{equation*}
Again, by contractibility of $S^\infty$, there exists $B_{2k+2} \in C_{2k+2}(S^{2k+2}, {\mathbb Z})$ such that 
\begin{equation*}
P_{2k+1} - \Delta_{2k+1} = (\tau-1) B_{2k+1} + \partial B_{2k+2}.\qedhere
\end{equation*}

Again, we assume that $\alpha$ is a single critical point; the case when $\alpha$ is a linear combination of critical points follows from the special case with only adding more notations. We can choose the inhomogeneous term $\nu^{eq}$ such that the moduli spaces ${\mathcal M}_Q(A; x_1, \ldots, x_p, y)$ are regular when $Q$ is equal to faces of $P_i$, $\Delta_i$, or $B_i$. Then by using 1-dimensional moduli spaces of the form ${\mathcal M}_{B_{i+1}}(A; \alpha, \ldots, \alpha, y)$, by Lemma \ref{lemmaa4}, one can see the following holds.
\begin{enumerate}

\item When $i = 2k$ is even, one has 
\begin{equation*}
\begin{split}
&\ QSt^{\rm Morse}_{p,i,A}(\alpha \otimes \cdots \otimes \alpha) - QSt^{\rm cell}_{p,i,A}(\alpha \otimes \cdots \otimes \alpha) \\
= &\ \sum_{y \in {\rm crit}(f)} \left( \#_p {\mathcal M}_{P_i}(A; \alpha, \ldots, \alpha, y) - \#_p {\mathcal M}_{\Delta_i}(A; \alpha, \ldots, \alpha, y) \right) \cdot y\\
= &\ \pm d \Big( \sum_{z \in {\rm crit} (f)} \#_p {\mathcal M}_{B_{2k+1}}(A; \alpha, \ldots, \alpha, z) \cdot z  \Big).
\end{split}
\end{equation*} 

\item When $i = 2k+1$ is odd, one has 
\begin{equation*}
\begin{split}
&\ QSt^{\rm Morse}_{p,i,A}(\alpha \otimes \cdots \otimes \alpha) - QSt^{\rm cell}_{p,i,A}(\alpha \otimes \cdots \otimes \alpha) \\
= &\ \sum_{y \in {\rm crit}(f)} \Big( \#_p {\mathcal M}_{P_i}(A; \alpha, \ldots, \alpha, y) - \#_p {\mathcal M}_{\Delta_i}(A; \alpha, \ldots, \alpha, y) \Big) \cdot y\\
= &\ \pm d \Big( \sum_{z \in {\rm crit} (f)} \#_p {\mathcal M}_{B_{2k+2}}(A; \alpha, \ldots, \alpha, z) \cdot z  \Big) \\
&\ + \sum_{y \in {\rm crit}(f)} \Big( \#_p {\mathcal M}_{\tau(B_{2k+1})}(A; \alpha, \ldots, \alpha, y) - \#_p {\mathcal M}_{B_{2k+1}} (A; \alpha, \ldots, \alpha, y) \Big) \cdot y.
\end{split}
\end{equation*} 
The last line vanishes by the ${\mathbb{Z}/p}$-invariance of the counts. 
\end{enumerate}
Therefore, the difference we are considering is a Morse coboundary.

\label{lemmab3}
Let $(H_0, J_0)$ be as in Lemma \ref{lemmab1}. For each $x \in {\mathcal O}(H_0)$, let $u_x: {\mathbb R}\times S^1 \to M$ be the constant Floer cylinder at $x$. Then for any collection of disjoint open neighborhoods $U(u_{x_1}), \ldots, U(u_{x_m})$ for all 1-periodic orbits of $H_0$, the following is true.

Let $\sigma$ be a Hamiltonian connection on ${\mathbb R}\times S^1$ which is equal to $H_\pm dt$ near $\pm \infty$ where $H_\pm$ are two nondegenerate Hamiltonians such that $\sigma$ is sufficiently close to $H_0 dt$ in $C^\infty$ topology on ${\mathbb R}\times S^1 \times M$ and such that $\int_{{\mathbb R}\times S^1} | F_\sigma| ds dt$ is sufficiently small. Let $J_{s, t}$ be a domain-dependent almost complex structure which is sufficiently close to $J_0$ in $C^\infty$ topology. Let $u: {\mathbb R} \times S^1 \to M$ be a solution to 
\begin{equation*}
(\nabla^\sigma u)^{0,1} = 0.
\end{equation*}
Then 
\begin{enumerate}

\item Suppose $u$ is asymptotic to $x_\pm \in {\mathcal O}(H_0, x)$ for some $x \in {\mathcal O}(H)$. Moreover, suppose there exists a capping $\overline{x}$ (which induces cappings $\overline{x}_\pm$ such that the concatenation of $\overline{x}_-$ with $u$ gives the capping $\overline{x}_+$). Then $u$ is contained in the neighborhood $U(u_x)$.


\item If the above assumption is not true, then $E(u) \geq \frac{1}{2}\epsilon_0$ where $\epsilon_0$ is from Lemma \ref{lemmab1}.
\end{enumerate}

The proof is based on a compactness argument and Lemma \ref{lemmab1}. Suppose the statement is not true. Then one can find a sequence $\sigma_i$ of Hamiltonian connection converging to $H_0 dt$ and a sequence of domain-dependent almost complex structures $J_i$ converging to $J_0$, both in $C^\infty$-topology, as well as a sequence of solutions $u_i$ to the equation $(\nabla^{\sigma_i} u_i)^{0,1} = 0$ which do not satisfy the claims. By choosing a subsequence (still indexed by $i$), one can argue in the following two situations.

\begin{enumerate}
    \item Suppose there exists $x \in {\mathcal O}(H_0)$ such that for all $i$, $u_i$ is asymptotic to $x_{i, \pm} \in {\mathcal O}(H_{i, \pm}, x)$. Moreover, for a fixed capping $\overline{x}$ of $x$ with induced ones $\overline{x}_{i, \pm}$, the concatenation of $\overline{x}_{i, -}$ with $u_i$ coincides with $\overline{x}_{i, +}$. The condition on the integral of $|F_{\sigma_i}|$ implies that $E(u_i) \to 0$. Then Lemma \ref{lemmab1} and the usual compactness argument imply that $u_i$ converges uniformly to the constant Floer cylinder $u_x$. Hence for $i$ sufficiently large, $u_i$ is contained in a $C^0$-neighborhood of $u_x$.

    \item Suppose for all $i$ we are not in the above situation for any $x \in {\mathcal O}(H_0)$. By contradiction, assume that $E(u_i) \leq \frac{1}{2} \epsilon_0$. Again one can apply the compactness argument. Lemma \ref{lemmab1} implies that any subsequential limit must be a constant Floer cylinder $u_x$ and the convergence is uniform. This implies that for $i$ sufficiently large, one is indeed in the first situation. \qedhere
\end{enumerate}

\label{lemmab4}
Let $H_0, J_0$ and $p$ be as in Lemma \ref{lemmab2}. Then for any collection of disjoint neighborhoods $U(u_{x_1}^p), \ldots, U(u_{x_m}^p) \subset C^0(\Sigma_p^\circ, M)$ with respect to the $C^0$-topology, the following is true.

Let $G$ be a nondegenerate Hamiltonian which is sufficiently close to $H_0$ in $C^\infty$-topology. Let $J$ be a compatible almost complex structure which is sufficiently close to $J_0$ in $C^\infty$-topology. Let $\sigma$ be the flat Hamiltonian connection on $\Sigma_p^\circ$ which is the pullback of $G dt$ on ${\mathbb R}\times S^1$. Let $u: \Sigma_p^\circ \to M$ be a solution to $(\nabla^\sigma u)^{0,1} = 0$. 

\begin{enumerate}
    \item Suppose there is $x \in {\mathcal O}(H_0)$ such that at the $j$-th negative puncture, $u$ is asymptotic to some $y_j \in {\mathcal O}(G, x)$ and at the positive puncture $u$ is asymptotic to $y_\infty \in {\mathcal O}(G^{(p)}, x^{(p)})$. Moreover, assume that for a  capping $\overline{x}$ of $x$ (which induces cappings $\overline{y}_j$ and $\overline{y}_\infty$), the concatenation of $\overline{y}_1\sqcup \cdots \sqcup \overline{y}_p$ with $u$ gives the capping $\overline{y}_\infty$. Then the map $u$ is contained in $U(u_x^p) \subset C^0(\Sigma_p^\circ, M)$. 

    \item If the above assumption is not true, then one has 
    \begin{equation*}
    E(u) \geq \frac{1}{2} \min \{ \epsilon_p, \epsilon_0(H_0^{(p)})\}
    \end{equation*}
    where $\epsilon_p$ is from Lemma \ref{lemmab2} and $\epsilon_0(H_0^{(p)})$ is from Lemma \ref{lemmab1} while replacing $H_0$ by $H_0^{(p)}$.
