\begin{align*}
    &\ \sigma_V: H(V) \to V,\ &\ \pi_V: V \to H(V)
\end{align*}
and a chain homotopy
\begin{equation*}
\Theta_V: V \to V
\end{equation*}
such that 
\begin{equation*}
\begin{split}
\pi_V \circ \sigma_V = &\ {\rm Id}_{H(V)},\\
\sigma_V \circ \pi_V = &\ {\rm Id}_V + d \circ \Theta_V + \Theta_V \circ d,\\
\Theta_V^2 = &\ 0,\\
\Theta_V \circ \sigma_V = &\ 0,\\
\pi_V \circ \Theta_V = &\ 0.
\end{split}
\end{equation*}

For each degree $n$, let $Z^n \subset V^n$ be the kernel of differential and $B^n = d(V^{n-1})$. As $H(V)$ is free, the exact sequence 
\begin{equation*}
\xymatrix{ 0 \ar[r] & B^n \ar[r] & Z^n \ar[r] & H^n \ar[r] & 0 }
\end{equation*}
splits. Choose a splitting
\begin{equation*}
V^n = Z^n \oplus B^{n+1} = B^n \oplus H^n \oplus B^{n+1}.
\end{equation*}
Then define $\sigma_V$ to be the inclusion of $H^n$ with respect to this splitting and $\pi_V$ to be the corresponding projection. Then define $\Theta_V$ to be the identification of $B^n \subset V^n$ with $B^n \subset V^{n-1}$, extended by $0$ on $H^n \oplus B^{n+1}$. It is then easy to see that all the conditions are satisfied.

When $i$ is sufficiently large, consider a continuation map 
\begin{equation*}
\Phi_i: CF(H_i) \to CF(H_i')
\end{equation*}
induced by a homotopy from $H_i$ to $H_i'$ which remains to be $C^\infty$-close to $H$. Then, using Lemma \ref{lemmab3}, we can decompose
\begin{equation*}
\Phi_i = \Phi_{\rm small} + \Phi_{\rm big},
\end{equation*}
where $\Phi_{\rm small}$ is the contribution from the continuation Floer cylinders whose energy is strictly less than $2 \epsilon_H$. One observes that, for each $\overline{x} \in \tilde {\mathcal O}(H)$, $\Phi_{\rm small}$ restricts to a chain homotopy equivalence between local Floer chain complexes. It follows from the construction of the modified action that $\Phi_i$ preserves the action filtration.

The direct limit map
\begin{equation*}
\varinjlim HF(H_i')^{{\mathcal A}_{H_i'}>a} \to \varinjlim HF(H_i)^{{\mathcal A}_H>a}
\end{equation*}
is an isomorphism.

The chain-level inclusion $CF(H_i')^{{\mathcal A}_{H_i'} >a} \to CF(H_i)^{{\mathcal A}_H>a}$ induces the long exact sequence
\begin{equation*}
\xymatrix{ HF(H_i)^{{\mathcal A}_{H_i'} \leq a < {\mathcal A}_H}   \ar[r] &    HF(H_i)^{{\mathcal A}_{H_i'} > a} \ar[r] & HF(H_i)^{{\mathcal A}_H>a} \ar[r] & HF(H_i)^{{\mathcal A}_{H_i'}\leq a < {\mathcal A}_H}}. 
\end{equation*}
By the exactness of the direct limit functor, it suffices to show that 
\begin{equation*}
\varinjlim HF(H_i)^{{\mathcal A}_{H_i'} \leq a < {\mathcal A}_H} = 0.
\end{equation*}
Indeed, given any $[c_i] \in HF(H_i)^{{\mathcal A}_{H_i'} \leq a < {\mathcal A}_H}$, there exists $\delta>0$ such that 
\begin{equation*}
{\mathcal A}_H([c_i]) > a + \delta.
\end{equation*}
Moreover $[c_i]$ can be represented by a cocycle 
\begin{equation*}
c_i \in CF(H_i)^{{\mathcal A}_H>a + \delta}.
\end{equation*}
Then for $j>i$ sufficiently large, the monotone continuation map from $CF(H_i)$ to $CF(H_j)$ sends $c_i$ to a cocycle $c_j$ with ${\mathcal A}_{H_j}(c_j) > a + \delta_j \Longrightarrow {\mathcal A}_{H_j'}(c_j) > a$. Hence $[c_i]$ cannot survive the direct limit.

We note that the complex $(C(H), {\mathcal A}_H)$ is actually well-defined up to filtered chain homotopy equivalence despite the auxiliary choices made in the proof. Indeed, given two sequences $H_i, H_i'$, for sufficiently large $i$, one has filtered chain homotopy equivalences
\begin{equation*}
C(H, H_i) \simeq CF(H_i) \simeq CF(H_i') \simeq C(H, H_i'),
\end{equation*}
where the homotopy equivalence $CF(H_i) \simeq CF(H_i')$ is defined via a continuation map and they are equipped with the modified action filtration.

We go through the homological perturbation in a slightly different way. Let $G$ be a nondegenerate perturbation of $H$ which is sufficiently close such that $G^{(p)}$ is also nondegenerate. Consider the equivariant Floer complex $CF_{{\mathbb{Z}/p}}(G^{(p)})$. By the discussion prior to Theorem \ref{thm213}, one can identify
\begin{equation*}
CF_{{\mathbb{Z}/p}}(G^{(p)}) \cong CF(G^{(p)}) \otimes {\mathcal{R}_p} \cong \Big( CF(G^{(p)}) \oplus CF(G^{(p)}) \otimes \theta \Big) \otimes {\mathcal{K}_{0, p}}.
\end{equation*}
Moreover, by Theorem \ref{thm213}, one can write the equivariant differential as 
\begin{equation*}
d_{{\mathbb{Z}/p}} = \left[ \begin{array}{cc} d_{G^{(p)}} & 0 \\ S_p & d_{G^{(p)}} \end{array} \right] + t K.
\end{equation*}
If we ignore the terms $S_p$ and $tK$, then via the homological perturbation construction given in the proof of Proposition \ref{prop31}, with $H$ replaced by $H^{(p)}$, one obtains copies of the complex $C(H^{(p)})$ with a differential $d_{H^{(p)}}$ which strictly increases the energy. One could, in addition, view the nilpotent term $S_p$ and the term  $tK$ having positive $t$ degrees as perturbations. Then one obtains a complex, denoted temporarily by 
\begin{equation*}
\widetilde{C}_{{\mathbb{Z}/p}}(H^{(p)}) \cong \Big( C(H^{(p)}) \oplus C(H^{(p)}) \otimes \theta \Big) \otimes {\mathcal{K}_{0, p}}
\end{equation*}
whose differential has the form 
\begin{equation*}
\widetilde{d}_{{\mathbb{Z}/p}} = \left[ \begin{array}{cc} d_{H^{(p)}} & 0 \\ \widetilde{S}_p & d_{H^{(p)}}    \end{array} \right] + t \widetilde{K}.
\end{equation*}
Further, it has the local part and ``high energy'' part, while the local part computes the local equivariant Floer cohomology. As $d_{H^{(p)}}$ has vanishing local parts, the local part of $\widetilde{d}_{{\mathbb{Z}/p}}$ reads
\begin{equation*}
\widetilde{d}_{{\mathbb{Z}/p}}^{\rm loc}  = \left[ \begin{array}{cc} 0 &  0 \\ \widetilde{S}_p^{\rm loc} & 0  \end{array} \right] + t\widetilde{K}^{\rm loc}.
\end{equation*}
However, one knows that the local equivariant cohomology is isomorphic to $HF^{\rm loc}(H^{(p)}, x^{(p)}) \otimes {\mathcal{R}_p}$. Hence $\widetilde{S}_p^{\rm loc}$ and $\widetilde{K}^{\rm loc}$ both vanish. This implies that the complex $\widetilde{C}_{{\mathbb{Z}/p}}(H^{(p)})$ is indeed a case of the complex $C_{{\mathbb{Z}/p}}(H^{(p)})$. Moreover, the difference $d_{{\mathbb{Z}/p}} - d_{H^{(p)}}$ strictly increases the energy filtration. Therefore, the bar-length spectrum of the complex $C_{{\mathbb{Z}/p}}(H^{(p)})$, if not empty, has no zero bars. Then by the forms of the ordinary and equivariant differentials, the assertion follows.

\cite[Definition 1.1]{Ruan_Tian_Bott}
Let $(M, \omega)$ be a closed symplectic manifold. Consider a Hamiltonian diffeomorphism $\phi\in \operatorname{\mathrm{Ham}}(M, \omega)$ and a connected component ${\mathcal F}$ of ${\rm Fix}_c(\phi)$. The connected component ${\mathcal F}$ is said to be of {\bf Morse--Bott type}\footnote{Notice that this condition is stronger than ${\rm graph}(\phi)$ intersects cleanly with the diagonal. The latter does not imply the equality between the eigenspace and generalized eigenspace of the eigenvalue $1$.} if ${\mathcal F}$ is a closed  submanifold and for each $x \in {\mathcal F}$
\begin{equation*}
T_x {\mathcal F} = {\rm Ker} (d\phi_x - {\rm Id}) = {\rm Ker} \big( (d\phi_x - {\rm Id})^{{\rm dim}_{\mathbb R} M} \big) \subset T_x M.
\end{equation*}

\label{lemmac2}
Let $H$ be a Hamiltonian on $(M, \omega)$ generating a diffeomorphism $\phi$ with Morse--Bott fixed points. Then for each $\omega$-compatible almost complex structure $J$, there exists $\epsilon_0 (H, J) >0$ and $\delta_0 >0$ satisfying the following conditions. Let $u: [0, +\infty) \times S^1 \to M$ be a finite energy solution to the Floer equation for $(H, J)$. Suppose $E(u) \leq \epsilon_0(H, J)$, then one has 
\begin{equation*}
\limsup_{s \to +\infty} e^{\delta_0 s} | \partial_s u(s, t)| < +\infty.
\end{equation*}

\label{corc3}
Let $H$ and $J$ be as above. Then there exists $\hbar_0(H, J) >0$ such that for any solution $u: {\mathbb R}\times S^1 \to M$ to the Floer equation for $(H, J)$, one has 
\begin{equation*}
E(u) > 0 \Longrightarrow E(u) \geq \hbar_0(H, J).
\end{equation*}

\label{lemmac5}
Let $H$ and $J$ be as in Lemma \ref{lemmac2}. Then for any open neighborhoods ${\mathcal U} \subset C^0({\mathbb R}\times S^1, M)$ of 
\begin{equation*}
\big\{ u_x\ |\ x \in {\mathcal O}(H)  \big\} \subset C^0( {\mathbb R}\times S^1, M)
\end{equation*}
the following is true.

Let $\sigma$ be a Hamiltonian connection on ${\mathbb R}\times S^1$ which is equal to $G_\pm dt$ near $\pm \infty$ where $G_\pm$ are two nondegenerate Hamiltonians which are sufficiently close to $H$ in the $C^\infty$-topology such that $\int_{{\mathbb R}\times S^1} |F_\sigma| ds dt$ is sufficiently small. Let $u: {\mathbb R}\times S^1 \to M$ be a solution to $(\nabla^\sigma u)^{0,1} = 0$ with respect to $J$. Then the following is true.
\begin{enumerate}
    \item Suppose $u$ is asymptotic to $x_\pm \in {\mathcal O}(G_\pm, {\mathcal F})$ for some component ${\mathcal F}$. Moreover, suppose there exists a capping $\overline{\mathcal F}$ (which induces cappings $\overline{x}_\pm$ such that the concatenation of $\overline{x}_-$ with $u$ gives the capping $\overline{x}_+$). Then $u$ is contained in the neighborhood ${\mathcal U}$.

    \item If the above assumption is not true, then $E(u_i) \geq \frac{1}{2}\hbar_0(H, J)$ where $\hbar_0(H, J)$ is from Corollary \ref{corc3}.
\end{enumerate}

\label{lemmac6}
Let $H, J$ and $p$ be as in Lemma \ref{lemmac4}. Then for any neighborhood ${\mathcal U}_p \subset C^0(\Sigma_p^\circ, M)$ of 
\begin{equation*}
\{ u_x^p\ |\ x \in {\mathcal O}(H)\}
\end{equation*}
with respect to the $C^0$-topology, the following is true. 

Let $G$ be a nondegenerate Hamiltonian which is sufficiently close to $H$ in $C^\infty$-topology. Let $\sigma$ be the flat Hamiltonian connection on $\Sigma_p^\circ$ which is the pullback of $G dt$ on ${\mathbb R}\times S^1$. Let $u: \Sigma_p^\circ \to M$ be a solution to $(\nabla^\sigma u)^{0,1} = 0$ with respect to $J$. Then
\begin{enumerate}
    \item Suppose there is a component ${\mathcal F}\subset {\mathcal O}(H)$ such that at the $j$-th negative puncture $u$ is asymptotic to some $y_j \in {\mathcal O}(G, {\mathcal F})$ and at the positive puncture $u$ is asymptotic to some $y_\infty \in {\mathcal O}(G^{(p)}, {\mathcal F}^{(p)})$. Moreover, assume that for a capping $\overline{\mathcal F}$ of ${\mathcal F}$ (which induces cappings $\overline{y}_j$ and $\overline{y}_\infty$), the concatenation of $\overline{y}_1 \sqcup \cdots \sqcup \overline{y}_p$ with $u$ gives the capping $\overline{y}_\infty$. Then the map $u$ is contained in ${\mathcal U}_p$.

    \item If the above assumption is not true, then one has 
