\item For any $k \geq 0$, the differential $d_{H^{(p^k)}}$ of the complex $C(H^{(p^k)})$ given by Proposition \ref{homological_perturbation_Morse_Bott} vanishes. Hence 
\begin{equation*}
HF(M; \Lambda^\Gamma) \cong \bigoplus_{{\mathcal F} \in \pi_0({\mathcal O}(H))} HF^{\rm loc}( H^{(p^k)}, {\mathcal F}^{(p^k)}; \Lambda^\Gamma).
\end{equation*}

\item For any $k \geq 1$, the differential $d_{{\mathbb{Z}/p}}$ of the complex $C_{{\mathbb{Z}/p}}(H^{(p^k)})$ given by Proposition \ref{propc14} vanishes. Hence
\begin{equation*}
HF_{\mathbb{Z}/p}(M; \Lambda_{{\mathcal{K}_{0, p}}}^\Gamma) \cong \bigoplus_{{\mathcal F} \in \pi_0({\mathcal O}(H))} HF_{\mathbb{Z}/p}^{\rm loc}(H^{(p^k)}, {\mathcal F}^{(p^k)}; \Lambda_{{\mathcal{K}_{0, p}}}^\Gamma).
\end{equation*}
\end{enumerate}

We follow the argument of \cite[Section 6.3]{AS-torsion}. First, because $\phi$ has order $p'$, there holds
\begin{equation*}
\max_{1 \leq j \leq p'-1}\beta_{\mathrm{tot}}(\phi^j) \geq \beta_{\mathrm{tot}}(\phi^{i \cdot p^k}).
\end{equation*}
Now we make use of the quantitative Smith inequality (Theorem \ref{thm219}), which is established for nondegenerate Hamiltonians. As the barcodes vary continuously with the Hamiltonian diffeomorphism, together with (2) of Proposition \ref{propc13}, for the degenerate Hamiltonian diffeomorphism $\phi^i$, one has
\begin{equation*}
\beta_{\rm tot}(\phi^{i \cdot p^k}) \geq p^k \beta_{\rm tot}(\phi^i).
\end{equation*} 
As $k$ is arbitrary, we see that $\beta_{\mathrm{tot}}(\phi^i) = 0$ for all $ i \in \{1, \ldots, p'\}$. In particular, the cochain complex $C(H^{(p^k)})$ does not admit any nontrivial differential.

For the complex $C_{{\mathbb{Z}/p}}(H^{(p^k)})$, suppose on the contrary it has a nontrivial differential $d_{{\mathbb{Z}/p}}$. Then the corresponding Tate complex $\widehat{C}_{{\mathbb{Z}/p}}(H^{(p^k)})$ also admits a nontrivial differential. As shown in Proposition \ref{propc14}, $d_{{\mathbb{Z}/p}}$ strictly increases the filtration. Then the Tate bar-length spectrum has a nonzero shortest bar-length $\widehat{\beta}_1(H^{(p^k)})$. It follows from Corollary \ref{corc16} that $\widehat{\beta}_1(H^{(p^k)}) = p \beta_1( H^{(p^{k-1})}) \neq 0$, which contradicts the first assertion we just proved.
